### ❓ পাঠভিত্তিক প্রশ্ন ও উত্তর (Comprehension Q&A)

> ❓ **প্রশ্ন: ‘প্রত্যুপকার’ শব্দের অর্থ কী এবং এর মূল বার্তা কী?**
> 💡 **উত্তর:** ‘প্রত্যুপকার’ শব্দের অর্থ উপকারের পরিবর্তে উপকার করা। গল্পের মূল বার্তা হলো মহৎ ব্যক্তিরা বিপদের দিনে উপকারীর ঋণ কখনো বিস্মৃত হন না এবং নিজের জীবন বিপন্ন করেও প্রত্যুপকার করেন।

> ❓ **প্রশ্ন: খলিফা মামুন বন্দি ব্যক্তির প্রতি কেন ক্ষমা প্রদর্শন করলেন?**
