### ❓ পাঠভিত্তিক প্রশ্ন ও উত্তর (Comprehension Q&A)

> ❓ **প্রশ্ন: ‘ফুলের বিবাহ’ গল্পে লেখক ফুলের বিবাহ কল্পনার মাধ্যমে কী ফুটিয়ে তুলেছেন?**
> 💡 **উত্তর:** লেখক রূপক ও কৌতুকপূর্ণ বর্ণনার মাধ্যমে প্রকৃতির রূপসৌন্দর্য এবং তৎকালীন সমাজজীবনের বিবাহরীতির নানা দিক শৈল্পিক ব্যঙ্গ ও আনন্দের সঙ্গে ফুটিয়ে তুলেছেন।

> ❓ **প্রশ্ন: প্রকৃতি ও মানবজীবনের মেলবন্ধন লেখক কীভাবে উপস্থাপন করেছেন?**
> 💡 **উত্তর:** লেখক মল্লিকা, গোলাপ ও অন্যান্য ফুলের রূপক চরিত্রের মধ্য দিয়ে মানব হৃদয়ের প্রেম, স্নেহ এবং সামাজিক আচার-অনুষ্ঠানকে জীবন্ত করে তুলেছেন।
