### 📚 শব্দার্থ ও টীকা : গর্ভের কলঙ্ক -সন্তান হিসেবে কলঙ্ক। গর্ভ হলো মায়ের পেট। যে ব্যক্তি বা বস্তুকে
পরিবারে নেতিবাচক হিসেবে দেখা হয় তা হলো কলঙ্ক। সুদীর্ঘ পল্পববিশিষ্ট - বড়ো পাতাবিশিষ্ট ৷ এখানে
চোখের পাতা হিসেবে ব্যবহৃত হয়েছে। ওষ্ঠাধর - ওষ্ঠ এবং অধর, উপরের ও নিচের ঠোট
[ওষ্ঠ+অধর _ ওষ্ঠাধর]। কিশলয় - গাছের নতুন পাতা । তর্জমা _ অনুবাদ, এক ভাষা থেকে অন্য ভাষায়
রূপান্তর । অস্তমান -_ ডুবন্ত, ডুবে যাচ্ছে এমন, চন্দ্র-সূর্যের পশ্চিম দিকে অদৃশ্য অবস্থা। অনিমেষ -
অপলক, পলকহীন। উদয়ান্ত- উদয় + অস্ত _উদয়াস্ত, আবির্ভাব ও তিরোভাব, ওঠা ও ডুবে যাওয়া ।
ছায়ালোক - ছায়া + আলোক _ ছায়ালোক। কোনো বস্তর ওপর আলো পড়লে বিপরীত দিকে যে প্রতিবিম্ব হয়
তা হলো ছায়া। বিজন মহত্ব - বিজন - জনশূন্য, নির্জন; মহত্ব - মহত্গুণ; বিজন মহত্ত্ব -
কোলাহলমুক্ত প্রকৃতির আকর্ষণীয় দিক। তন্বী ক্ষীণ ও সুগঠিত অঙ্গবিশিষ্ট | বাখারি - কীধের
দুদিকে দুপ্রান্তে ঝুলিয়ে বোঝা বহনের বাশের ফালি। টেকিশালা - যে ঘরে টেকি রাখা হয়। টেকি হলো
» ধান থেকে চাল তৈরির লোকজ যন্ত্র। এখনো গ্রামীণ জীবনে অনেক বাড়িতে টেকির ঘর
&$ আছে । গার্হস্থ্য সচ্ছলতা - পারিবারিক দৈনন্দিন জীবনের সচ্ছলতা । চিরনিস্তব্ধ হর্দয়

উপকূল - শান্ত হৃদয়। বিল্লিরব পূর্ণ -বিঝি পোকার আওয়াজ/শব্দে মুখর। বিজনমূর্তি - নির্জন

অবস্থা । বিজন হলো নির্জম বা জনমানবশূন্য, মূর্তি হলো কোনোকিছুর প্রতিকৃতি।
বিজনমূর্তি শব্দটি এখানে কোলাহলহীন অবস্থা বা নির্জন/জনমানবশূন্য অবস্থা বোঝাতে ব্যবহৃত হয়েছে।
গণ্ডদেশ - গাল। মুক - বধির, বোবা। বিষাদশান্ত - দুঃখমগ্র, বিষাদ ₹ স্থৃত্তিশৃন্যতা, বিষণ্তা। বিষাদশান্ত
হলো খুব বেশি বিষাদগস্ততা থেকে যে শান্ত অবস্থা ।পুর্ণিমাতিথি - চাদের পরিপূর্ণ রূপ হওয়ার সময়।
কন্যাভারগ্রস্ত পিতা-মাতা- যে পিতা-মাতার বিবাহযোগ্যা কন্যা সন্তানের বিয়ে হয়নি। কপোল -গাল।
নেত্রপল্পৰ - চোখের পাতা। শুর্াছাদশী - টাদের বারোতম দিন। শম্পশয্যায়- কচি ঘাসে আবৃত বিছানা ।

