### 📝 পাঠ-পরিচিতি : “সুভা” গল্পটি রবীন্দ্রনাথ ঠাকুরের বিখ্যাত গল্পগুচ্ছ থেকে সংকলিত হয়েছে।
বাক্প্রতিবন্ধী কিশোরী সুভার প্রতি লেখকের হৃদয় নিংড়ানো ভালোবাসা ও মমতৃবোধে গল্পটি অমর
হয়ে আছে। সুভা কথা বলতে পারে না। মা মনে করেন, এ তার নিয়তির দোষ, কিন্তু বাবা তাকে
ভালোবাসেন । আর কেউ তার সঙ্গে মেশে না, খেলে না। কিন্তু তার বিশাল একটি আশ্রয়ের জগৎ
আছে। যারা কথা বলতে পারে না সেই পোষা প্রাণীদের কাছে সে মুখর ৷ তাদের সে খুবই কাছের জন।
আর বিপুল নির্বাক প্রকৃতির কাছে সে পায় মুক্তির সনদ । “সুভা" গল্পের মাধ্যমে রবীন্দ্রনাথ ঠাকুর বিশেষ
চাহিদাসম্পন্ন শিশুর মন ও চিন্তা, আবেগ ও অনুভূতির সুক্মতর দিকগুলো উপস্থাপন করেছেন। বিশেষ
চাহিদা সম্পন্ন শিক্ষার্থীদের মনোজগতে সকলের প্রতি মমতৃশীল দৃষ্টিভি প্রস্তুতে সহায়তা করে এ গল্প ।

