### ❓ পাঠভিত্তিক প্রশ্ন ও উত্তর (Comprehension Q&A)

> ❓ **প্রশ্ন: রবীন্দ্রনাথ ঠাকুরের মতে ‘লাইব্রেরি’ মানবজীবনের কোন চিরন্তন দিকটি ধারণ করে?**
> 💡 **উত্তর:** লাইব্রেরি হলো মানবাত্মার অমর মহাসমুদ্র, যেখানে যুগে যুগে সঞ্চিত মানুষের আনন্দ-বেদনা, চিন্তা ও জ্ঞানের চিরন্তন স্রোত শান্তভাবে স্তব্ধ হয়ে মানুষের কল্যাণে সংরক্ষিত থাকে।

> ❓ **প্রশ্ন: লাইব্রেরিকে কেন 'শব্দহীন মহাসমুদ্র' বলা হয়েছে?**
> 💡 **উত্তর:** লাইব্রেরির নীরব বইগুলোর ভেতর কোটি কোটি মানুষের মনের ভাব, ইতিহাস ও বাণী চিরকালের মতো ঘুমিয়ে থাকে, যা পাঠক স্পর্শ করামাত্র জীবন্ত হয়ে ওঠে।
