### ✍️ মূল পাঠ্যবইয়ের সৃজনশীল প্রশ্ন

জাতীয় জীবনধারা গঙ্গা-যমুনার মতোই দুই ধারায় প্রবাহিত। এক ধারার নাম আত্মরক্ষা বা স্বার্থপ্রসার,
আরেক ধারার নাম আত্মপ্রকাশ বা পরমার্থ বৃদ্ধি। একদিকে যুদ্ধবিগ্রহ, মামলা-ফ্যাসাদ প্রভৃতি কদর্য
দিক; অপরদিকে সাহিত্য, শিল্প, ধর্ম প্রভৃতি কল্যাণপ্রদ দিক। একদিকে শুধু কাজের জন্য কাজ।
অপরদিকে আনন্দের জন্য কাজ। একদিকে সংগ্রহ, আরেক দিকে সৃষ্টি। যে জাতি দ্বিতীয় দিকটির
প্রতি উদাসীন থেকে শুধু প্রথম দিকটির সাধনা করে, সে জাতি কখনও উঁচু জীবনের অধিকারী হতে
পারে না।

ক. ভীড়েও ভবানী" অর্থ কী?

গ. উদ্দীপকে বর্ণিত প্রথম দিকটি “বই পড়া" প্রবন্ধের যে দিকটিকে ইঙ্গিত করে তা ব্যাখ্যা করো।

ঘ. “উদ্দীপকে পরমার্থ বৃদ্ধির প্রতি যে গুরুত্ব দেওয়া হয়েছে তা “বই পড়া" প্রবন্ধের লেখকের মতকে
সমর্থন করে”- মন্তব্যটির বিচার করো ।

