### ❓ পাঠভিত্তিক প্রশ্ন ও উত্তর (Comprehension Q&A)

> ❓ **প্রশ্ন: প্রমথ চৌধুরীর মতে সাহিত্যচর্চাকে কেন শিক্ষার প্রধান অঙ্গ বলা উচিত?**
> 💡 **উত্তর:** সাহিত্য মানুষের মনকে সচল, সজাগ ও প্রসারিত করে। কেবল অর্থকরী বিদ্যা অর্জন করলে মানুষের আত্মার বিকাশ ঘটে না; সাহিত্যচর্চাই মানুষের আত্মিক মুক্তি নিশ্চিত করে।

> ❓ **প্রশ্ন: ‘বই পড়া’ প্রবন্ধে লেখক প্রচলিত শিক্ষার কোন ত্রুটির সমালোচনা করেছেন?**
> 💡 **উত্তর:** লেখক সার্টিফিকেটসর্বস্ব ও পরীক্ষাকেন্দ্রিক মুখস্থ বিদ্যার সমালোচনা করেছেন, যা মানুষের মনের স্বাধীন স্ফূর্তি নষ্ট করে এবং প্রকৃত জ্ঞান অর্জন থেকে দূরে সরিয়ে দেয়।
