## 📖 মূল পাঠ (গদ্য)

অভাগীর স্বর্গ
শরৎচন্দ্র চট্টোপাধ্যায়



ঠাকুরদাস মুখুয্যের বধীয়সী স্ত্রী সাতদিনের জুরে মারা গেলেন। বৃদ্ধ মুখোপাধ্যায় মহাশয় ধানের
জামাইরা- প্রতিবেশীর দল, চাকর-বাকর - সে যেন একটা উৎসব বাঁধিয়া গেল। সমস্ত গ্রামের লোক
করিয়া আলতা এবং মাথায় ঘন করিয়া সিন্দুর লেপিয়া দিল, বধুরা ললাট চন্দনে চর্চিত করিয়া
পুম্পে, পত্রে, গন্ধে, মাল্যে, কলরবে মনে হইল না এ কোনো শোকের ব্যাপার-এ যেন বড়বাড়ির
গৃহিণী পঞ্চাশ বর্ষ পরে আর একবার নূতন করিয়া তীহার স্বামীগৃহে যাত্রা করিতেছেন । বৃদ্ধ
মুখোপাধ্যায় শান্তমুখে তাহার চিরদিনের সঙ্গিনীকে শেষ বিদায় দিয়া অলক্ষে দুফোটা চোখের জল
মুছিয়া শোকার্ত কন্যা ও বধূগণকে সান্তনা দিতে লাগিলেন । প্রবল হরিধ্বনিতে প্রভাত-আকাশ
আলোড়িত করিয়া সমস্ত গ্রাম সঙ্গে সঙ্গে চলিল। আর একটি প্রাণী একটু দূরে থাকিয়া এই দলের
সঙ্গী হইল। সে কাঙালীর মা। সে তাহার কুটির-প্রাঙ্গণে গো্টা-কয়েক বেগুন তুলিয়া এই পথে
হাটে চলিয়াছিল, এই দৃশ্য দেখিয়া আর নড়িতে পারিল না। রহিল তাহার হাটে যাওয়া, রহিল তাহার
আঁচলেবেগুন বাধা,_সে চোখের জল মুছিতে মুছিতে সকলের পিছনে শ্বশানে আসিয়া উপস্থিত হইল।
গ্রামের একান্তে গরুড়-নদীর তীরে শ্বুশীন। সেখানে পূর্বাহেই কাঠের ভার, চন্দনের টুকরা, ঘৃত,
মধু, ধূপ, ধুনা প্রভৃতি উপকরণ সঞ্চিত হইয়াছিল, কাঙালীর মা ছোটজাত, দুলের মেয়ে বলিয়া
কাছে যাইতে সাহস পাইল না, তফাতে একটা উচু টিপির মধ্যে দীড়াইয়া সমস্ত অন্ত্যেষ্টিক্রিয়া প্রথম
হইতে শেষ পর্যন্ত উৎসুক আগ্রহে চোখ মেলিয়া দেখিতে লাগিল। প্রশস্ত ও পর্যাপ্ত চিতার পরে যখন
শব স্থাপিত করা হইল তখন তাহার রাঙা পা-দুখানি দেখিয়া তাহার দু'চক্ষু জুড়াইয়া গেল, ইচ্ছা হইল
ছুটিয়া গিয়া একবিন্দু আলতা মুছাইয়া লইয়া মাথায় দেয়। বহুকণ্ঠের হরিধ্বনির সহিত পুত্রহস্তের
£ মন্ত্রপূত অগ্নি যখন সংযোজিত হইল তখন তাহার চোখ দিয়া ঝরঝর করিয়া জল পড়িতে লাগিল,

মনে মনে বারংবার বলিতে লাগিল, ভাগ্যিমানী মা, তুমি সগ্যে যাচ্চো-আমাকেও আশীর্বাদ
করে যাও, আমিও যেন এমনি কাঙালীর হাতের আগুনটুকু পাই। ছেলের হাতের আগ্তন! সে ত
সোজা কথা নয়! স্বামী, পুত্র, কন্যা, নাতি, নাতনী, দাস, দাসী পরিজন-সমস্ত সংসার উজ্জ্বল
রাখিয়া এই যে স্বর্গারোহণ- দেখিয়া তাহার বুক ফুলিয়া ফুলিয়া উঠিতে লাগিল, এ সৌভাগ্যের
সে যেন আর ইয়ন্তা করিতে পারিল না। সদ্য-প্রজুলিত চিতার অজস্র ধুয়া নীল রঙের ছায়া ফেলিয়া
ঘুরিয়া ঘুরিয়া আকাশে উঠিতেছিল, কাঙালীর মা ইহারই মধ্যে ছোট একখানি রথের চেহারা যেন
ভিতরে কে যেন বসিয়া আছে-মুখ তাহার চেনা যায় না, কিন্তু সিঁথায় তাহার সিঁদুরের রেখা,
পদতল- দুটি আলতায় রাঙানো । উর্ধ্বদৃষ্টে চাহিয়া কাঙালীর মায়ের দুই চোখে অশ্রুর ধারা
তুই দাড়িয়ে আছিস মা, ভাত রীধবি নেঃ

মা চমকিয়া ফিরিয়া চাহিয়া কহিল, রীধবো”খন রে! হঠাৎ উপরে অঙ্গুলি নির্দেশ করিয়া ব্যগ্রস্বরে
কহিল, দ্যাখ দ্যাখ বাবা,_বামুন-মা ওই রথে চড়ে সগ্যে যাচ্ছে!

ছেলে বিস্ময়ে মুখ তুলিয়া কহিল, কৈ? ক্ষণকাল নিরীক্ষণ করিয়া শেষে বলিল, তুই ক্ষেপেছিস! ও
ত ধুয়া! রাগ করিয়া কহিল, বেলা দুপুর বাজে, আমার ক্ষিদে পায় না বুঝি? এবং সঙ্গে সঙ্গে মায়ের
চোখে জল লক্ষ করিয়া বলিল, বামুনদের গিনি মরছে তুই কেন কেঁদে মরিস মা?

কাঙালীর মার এতক্ষণে হুশ হইল । পরের জন্য শ্শানে দীড়াইয়া এইভাবে অশ্রুপাত করায় সে
মনে মনে লজ্জা পাইল, এমন কি, ছেলের অকল্যাণের আশঙ্কায় মুহূর্তে চোখ মুছিয়া ফেলিয়া
একটুখানি হাসিবার চেষ্টা করিয়া বলিল, কাদব কিসের জন্যে রে !- চোখে ধো লেগেছে বৈ ত নয়!

হাঃ-ধো লেগেছে বৈ ত না ! তুই কাঁদতেছিলি!

মা আর প্রতিবাদ করিল না। ছেলের হাত ধরিয়া ঘাটে নামিয়া নিজেও স্নান করিল, কাঙালীকেও স্নান
করাইয়া ঘরে ফিরিল,_শ্বশান-সৎকারের শেষটুকু দেখা আর তার ভাগ্যে ঘটিল না।

শুধু হাস্য করিয়াই ক্ষান্ত হন না, তীব্র প্রতিবাদ করেন। তাই তাহাদের সমস্ত জীবনটা তাহাদের
নিজের নামগ্ুলোকেই যেন আমরণ ভ্যাঙচাইয়া চলিতে থাকে । কাঙালীর মার জীবনের ইতিহাস
ছোটো, কিন্ত সেই ছোট্ট কাঙালজীবনটুকু বিধাতার এই পরিহাসের দায় হইতে অব্যাহতি লাভ
করিয়াছিল। তাহাকে জন্ম দিয়া মা মরিয়াছিল, বাপ রাগ করিয়া নাম দিল অভাগী। মা নাই, বাপ
নদীতে মাছ ধরিয়া বেড়ায়, তাহার না আছে দিন, না আছে রাত। তবু যে কি করিয়া ক্ষুদ্র অভাগী
একদিন কাঙালীর মা হইতে বাঁচিয়া রহিল সে এক বিস্ময়ের বন্ত। যাহার সহিত বিবাহ হইল তাহার
নাম রসিক বাঘ, বাঘের অন্য বাঘিনী ছিল, ইহাকে লইয়া সে গ্রামান্তরে উঠিয়া গেল, অভাগী তাহার
অভাগ্য ও শিশুপুত্র কাঙালীকে লইয়া গ্রামেই পড়িয়া রহিল।

