০
1


তাহার সেই কাঙালী বড়ো হইয়া আজ পনেরোয় পা দিয়াছে। সবেমাত্র বেতের কাজ শিখিতে আরম্ত
করিয়াছে, অভাগীর আশা হইয়াছে আরও বছরখানেক তাহার অভাগ্যের সহিত যুঝিতে পারিলে দুঃখ
ঘুচিবে। এই দুঃখ যে কি, যিনি দিয়াছেন তিনি ছাড়া আর কেহই জানে না।

কাঙালী পুকুর হইতে আঁচাইয়া আসিয়া দেখিল তাহার পাতের ভুক্তাবশেষ মা একটা মাটির পাত্রে
ঢাকিয়া রাখিতেছে, আশ্চর্য হইয়া জিজ্ঞাসা করিল, তুই খেলি নে মা?

বেলা গড়িয়ে গেছে বাবা, এখন আর ক্ষিদে নেই।

এই ছলনায় বহুদিন কাঙালীর মা কাঙালীকে ফাঁকি দিয়া আসিয়াছে । সে হাঁড়ি দেখিয়া তবে ছাড়িল।
তাহাতে আর একজনের মত ভাত ছিল । তখন সে প্রসন্রমুখে মায়ের কোলে গিয়া বসিল। এই বয়েসের
ছেলে সচরাচর এরূপ করে না, কিন্তু শিশুকাল হইতে বহুকাল যাবৎসে রুগ্ন ছিল বলিয়া মায়ের

খেলাধুলার সাধ মিটাইতে হইয়াছে ।

একহাতে গলা জড়াইয়া, মুখের উপর মুখ রাখিয়াই কাঙালী চকিত হইয়া কহিল, মা, তোর গা
যে গরম, কেন তুই অমন রোদে দীড়িয়ে মড়া-পোড়ানো দেখতে গেলি? কেন আবার নেয়ে এলি?

মড়া-পোড়ানো কি তুই_

মা শশব্যস্তে ছেলের মুখে হাত চাপা দিয়া কহিল, ছি বাবা, মড়া-পোড়ানো বলতে নেই, পাপ হয়।
সতী-লক্ষমী মা-ঠাকরুন রথে করে সগ্যে গেলেন ।

ছেলে সন্দেহ করিয়া কহিল, তোর এক কথা মা! রথে চড়ে কেউ নাকি আবার সগ্যে যায় ।

মা বলিল, আমি যে চোখে দেখনু কাঙালী, বামুন-মা রথের উপরে বসে। তেনার রাঙা পা-দুখানি
যে সবাই চোখ মেলে দেখলে রে!

সবাই দেখলে?
সব্বাই দেখলে ।

কাঙালী মায়ের বুকে ঠেস দিয়া বসিয়া ভাবিতে লাগিল । মাকে বিশ্বাস করাই তাহার অভ্যাস, বিশ্বাস
করিতেই সে শিশুকাল হইতে শিক্ষা করিয়াছে, সেই মা যখন বলিতেছে সবাই চোখ মেলিয়া এত বড়ো
ব্যাপার দেখিয়াছে,তখন অবিশ্বাস করিবার আর কিছু নাই। খানিক পরে আস্তে আস্তে কহিল, তাহলে
তুইও ত মা সগ্যে যাবি? বিন্দির মা সেদিন রাখালের পিসিকে বলতেছিল, ক্যাঙ্লার মার মত সতী-
লক্ষ্মী আর দুলে-পাড়ায় নেই।

কাঙালীর মা চুপ করিয়া রহিল, কাঙালী তেমনি ধীরে ধীরে কহিতে লাগিল, বাবা যখন তোরে ছেড়ে
দিলে, তখন তোরে কত লোকে ত নিকে করতে সাধাসাধি করলে । কিন্তু তুই বললি, না। বললি,
ক্যাঙালী বাচলে আমার দুঃখু ঘুচবে, আবার নিকে করতে যাবো কিসের জন্যে? হা মা, তুই
নিকে করলে আমি কোথায় থাকতুম? আমি হয়ত না খেতে পেয়ে এতদিনে কবে মরে যেতুম |

মা ছেলেকে দুই হাতে বুকে চাপিয়া ধরিল। বন্তত সেদিন তাহাকে এ পরামর্শ কম লোকে দেয় নাই,
এবং যখন সে কিছুতেই রাজি হইল না, তখন উৎপাত-উপদ্রবও তাহার প্রতি সামান্য হয় নাই, সেই
কথা স্মরণ করিয়া অভাগীর চোখ দিয়া জল পড়িতে লাগিল । ছেলে হাত দিয়া মুছাইয়া দিয়া বলিল,
ক্যাতাটা পেতে দেব মা, শুবি?

মা চুপ করিয়া রহিল। কাঙালী মাদুর পাতিল, কীথা পাতিল, মাচার উপর হইতে ছোট বালিশটি পাড়িয়া
দিয়া হাত ধরিয়া তাহাকে বিছানায় টানয়া লইয়া যাইতে, মা কহিল, কালী, আজ তোর আর কাজে গিয়ে
কাজ |

কাজ কামাই করিবার প্রস্তাব কাঙালীর খুব ভালো লাগিল, কিন্তু কহিল, জলপানির পয়সা দুটো ত
তা হলে দেবেনামা!

না দিক গে, -আয় তোকে রূপকথা বলি ।
আর প্রলুব্ধ করিতে হইল না, কাঙালী তৎক্ষণাৎ মায়ের বুক ঘেঁষিয়া শুইয়া পড়িয়া কহিল, বল্‌ তা হলে।
রাজপুত্বুর, কোটালপুত্ুর আর সেই পক্ষীরাজ ঘোড়া_

অভাগী রাজপুত্র, কোটালপুত্র আর পক্ষীরাজ ঘোড়ার কথা দিয়া গল্প আরম্ভ করিল। এ-সকল তাহার
পরের কাছে কতদিনের শোনা এবং কতদিনের বলা উপকথা । কিন্তু মুহূর্ত-কয়েক পরে কোথায় গেল
তাহার রাজপুত্র, আর কোথায় গেল তাহার কোটালপুত্র-সে এমন উপকথা শুরু করিল যাহা পরের কাছে
মস্তিষ্কে বহিতে লাগিল, ততই সে যেন নব নব উপকথার ইন্দ্রজাল রচনা করিয়া চলিতে লাগিল।
তাহার বিরাম নাই, বিচ্ছেদ নাই- কাঙালীর স্বল্প দেহ বার বার রোমাঞ্চিত হইতে লাগিল। ভয়ে,
বিস্ময়ে, পুলকে সে সজোরে মায়ের গলা জড়াইয়া তাহার বুকের মধ্যে যেন মিশিয়া যাইতে চাহিল।

বাহিরে বেলা শেষ হইল, সূর্য অস্ত গেল, সন্ধ্যার ম্লান ছায়া গাঢ়ুতর হইয়া চরাচর ব্যাপ্ত করিল,
কিন্তু ঘরের মধ্যে আজ আর দীপ জুলিল না, গৃহস্থের শেষ কর্তব্য সমাধা করিতে কেহ উঠিল না,
নিবিড় অন্ধকারে কেবল রুগ্ন মাতার অবাধ গুঞ্জন নিস্তব্ধ পুত্রের কর্ণে সুধাবর্ষণ করিয়া চলিতে লাগিল।
সে সেই শ্শান ও শ্শানযাত্রার কাহিনি । সেই রথ, সেই রাঙ্গা পা-টি, সেই তার স্বর্গে যাওয়া।
ছেলেরা মাতাকে বহন করিয়া লইয়া গেল, তার পরে সন্তানের হাতের আগুন । সে আগ্তন ত আগ্তন
নয় কাঙালী, সে ত হরি! তার আকাশজোড়া ধুয়ো ত ধুয়ো নয় বাবা, সেই ত সগ্যের রথ!
কাঙালীচরণ, বাবা আমার!

কি মা?
তোর হাতের আগুন যদি পাই বাবা, বামুন-মার মত আমিও সগ্যে যেতে পাবো।
কাঙালী অস্ফুটে শুধু কহিল, যাঃ-বলতে নেই।

হুঁ
০
4


মা সেকথা বোধ করি শুনিতেই পাইল না, তগ্তনিঃশ্বাস ফেলিয়া বলিতে লাগিল, ছোটোজাত বলে
তখন কিন্তু কেউ ঘেন্না করতে পারবে না-দুঃখী বলে কেউ ঠেকিয়ে রাখতে পারবে না।
ইস! ছেলের হাতের আগ্তন,-রথকে যে আসতেই হবে।

ছেলে মুখের উপর মুখ রাখিয়া ভগ্নকণ্ঠে কহিল, বলিস নে মা, বলিস নে, আমার বড্ড ভয় করে।

মা কহিল, আর দেখু কাঙালী, তোর বাবাকে একবার ধরে আনবি, অমনি যেন পায়ের ধুলো
মাথায় দিয়ে আমাকে বিদায় দেয়। অমনি পায়ে আলতা, মাথায় সিঁদুর দিয়ে,_কিন্ত কে বা দেবে?
তুই দিবি, না রে কাঙালী? তুই আমার ছেলে, তুই আমার মেয়ে, তুই আমার সব! বলিতে বলিতে সে
ছেলেকে একেবারে বুকে চাপিয়া ধরিল ।

অভাগীর জীবন-নাট্যের শেষ অঙ্ক পরিসমাপ্ত হইতে চলিল। বিস্তৃতি বেশি নয়, সামান্যই । বোধ করি
ত্রিশটা বসর আজও পার হইয়াছে কি হয় নাই, শেষও হইল তেমনি সামান্যভাবে । গ্রামে কবিরাজ
ছিল না, ভিন্ন গ্রামে তাহার বাস। কাঙালী গিয়া কাদাকাটি করিল, হাতে-পায়ে পড়িল, শেষে ঘটি
বাধা দিয়া তাহাকে এক টাকা প্রণামী দিল। তিনি আসিলেন না, গোটা-চারেক বড়ি দিলেন। তাহার
কত কি আয়োজন । খল, মধু আদার সত্ত্ব, তুলসীপাতার রস-কাঙালীর মা ছেলের প্রতি রাগ করিয়া
বলিল, কেন তুই আমাকে না বলে ঘটি বাধা দিতে গেলি বাবা! হাত পাতিয়া বড়ি কয়টি গ্রহণ করিয়া

মাথায় ঠেকাইয়া উনানে ফেলিয়া দিয়া কহিল, ভালো হই ত এতেই হবো, বাগদি-দুলের ঘরে কেউ
কখনো ওষুধ খেয়ে বাচে না।

দিন দুই-তিন এমনি গেল। প্রতিবেশীরা খবর পাইয়া দেখিতে আসিল, যে যাহা মুষ্টিযোগ জানিত,
হরিণের শি-ঘষা জল, গেঁটে-কড়ি পুড়াইয়া মধুতে মাড়িয়া চাটাইয়া দেওয়া ইত্যাদি অব্যর্থ ওষধের
সন্ধান দিয়া যে যাহার কাজে গেল। ছেলেমানুষ কাঙালী ব্যতিব্যস্ত হইয়া উঠিতে, মা তাহাকে কাছে
টানিয়া লইয়া কহিল, কোবরেজের বড়িতে কিছু হলো না বাবা আর ওদের ওষুধে কাজ হবে? আমি
এমনি ভালো হবো ।

কাঙালী কাদিয়া কহিল, তুই বড়ি ত খেলি নে মা, উনুনে ফেলে দিলি । এমনি কি কেউ সারে?

আমি এমনি সেরে যাবো । তার চেয়ে তুই দুটো ভাতে-ভাত ফুটিয়ে নিয়ে খা দিকি, আমি চেয়ে দেখি ।

কাঙালী এই প্রথম অপটু হস্তে ভাত রীধিতে প্রবৃত্ত হইল । না পারিল ফ্যান ঝাড়িতে, না পারিল ভালো
ছড়াইয়া পড়ে; মায়ের চোখ ছলছল করিয়া আসিল। নিজে একবার উঠিবার চেষ্টা করিল, কিন্তু মাথা
সোজা করিতে পারিল না, শয্যায় লুটাইয়া পড়িল । খাওয়া হইয়া গেলে ছেলেকে কাছে লইয়া কি
করিয়া কি করিতে হয় বিধিমতে উপদেশ দিতে গিয়া তাহার ক্ষীণকণ্ঠ থামিয়া গেল, চোখ দিয়া কেবল

গ্রামে ঈশ্বর নাপিত নাড়ী দেখিতে জানিত, পরদিন সকালে সে হাত দেখিয়া তাহারই সুমুখে মুখ গম্ভীর
করিল, দীর্ঘশ্বাস ফেলিল এবং শেষে মাথা নাড়িয়া উঠিয়া গেল। কাঙালীর মা ইহার অর্থ বুঝিল, কিন্তু
তাহার ভয়ই হইল না। সকলে চলিয়া গেলে সে ছেলেকে কহিল, এইবার একবার তাকে ডেকে
আনতে পারিস বাবা?

কাকে মা?

ওই যে রে-ও-গাঁয়ে যে উঠে গেছে-
কাঙালী বুঝিয়া কহিল, বাবাকে?
অভাগী চুপ করিয়া রহিল।

কাঙালী বলিল, সে আসবে কেন মা?

অভাগীর নিজেরই যথেষ্ট সন্দেহ ছিল, তথাপি আস্তে আস্তে কহিল, গিয়ে বলবি, মা শুধু একটু তোমার
পায়ের ধুলো চায় ।
সে তখনি যাইতে উদ্যত হইলে সে তাহার হাতটা ধরিয়া ফেলিয়া বলিল, একটু কাদাকাটা করিস বাবা,
বলিস মা যাচ্চে।

একটু থামিয়া কহিল, ফেরবার পথে অমনি নাপতে-বৌদির কাছ থেকে একটু আলতা চেয়ে আনিস
কাঙালী, আমার নাম করলেই সে দেবে । আমাকে বড় ভালোবাসে ।

ভালো তাহাকে অনেকেই বাসিত। জুর হওয়া অবধি মায়ের মুখে সে এই কয়টা জিনিসের কথা
এতবার এতরকম করিয়া শুনিয়াছে যে, সে সেইখান হইতে কীদিতে কীদিতে যাত্রা করিল।

পরদিন রসিক দুলে সময়মত যখন আসিয়া উপস্থিত হইল তখন অভাগীর আর বড় জ্ঞান নাই।
মুখের পরে মরণের ছায়া পড়িয়াছে, চোখের দৃষ্টি এ সংসারের কাজ-সারিয়া কোথায় কোন্‌ অজানা
দেশে চলিয়া গেছে।

কাঙালী কাঁদিয়া কহিল, মাগো ! বাবা এসেছে-পায়ের ধুলো নেবে যে!

মা হয়ত বুঝিল, হয়ত বুঝিল না, হয়ত বা তাহার গভীর সঞ্চিত বাসনা সংস্কারের মত তাহার আচ্ছন্ন
চেতনায় ঘা দিল। এই মৃত্যুপথ-যাত্রী তাহার অবশ বাহুখানি শয্যার বাহিরে বাড়াইয়া হাত পাতিল ।

কেহ নাকি চাহিতে পারে তাহা তাহার কল্পনার অতীত । বিন্দির পিসি দীড়াইয়া ছিল, সে কহিল,
দাও বাবা, দাও একটু পায়ের ধুলো ।

রসিক অগ্রসর হইয়া আসিল। জীবনে যে স্ত্রীকে সে ভালোবাসা দেয় নাই, অশন-বসন দেয় নাই,
কোন খোঁজখবর করে নাই, মরণকালে তাহাকে সে শুধু একটু পায়ের ধুলা দিতে গিয়া কীদিয়া ফেলিল।
রাখালের মা বলিল, এমন সতীলক্ষ্মী বামুন-কায়েতের ঘরে না জন, ও আমাদের দুলের ঘরে জন্মালে কেন!
এইবার ওর একটু গতি করে দাও বাবা-ক্যাঙালার হাতের আগুনের লোভে ও যেন প্রাণটা দিলে ।

অভাগীর অভাগ্যের দেবতা অগোচরে বসিয়া কি ভাবিলেন জানি না, কিন্তু ছেলেমানুষ কাঙালীর বুকে
গিয়া এ কথা যেন তীরের মত বিধিল।


সেদিন দিনের বেলাটা কাটিল, প্রথম রাত্রিটা কাটিল, কিন্তু প্রভাতের জন্য কাঙালীর মা আর অপেক্ষা
করিতে পারিল না। কি জানি, এত ছোটজাতের জন্যও স্বর্গে রথের ব্যবস্থা আছে কি না, কিংবা
অন্ধকারে পায়ে হাটিয়াই তাহাদের রওনা হইতে হয়,_কিন্তু এটা বুঝা গেল, রাত্রি শেষ না হইতেই এ
দুনিয়া সে ত্যাগ করিয়া গেছে।

কুটির-প্রাঙ্গণে একটা বেলগাছ, একটা কুড়ল চাহিয়া আনিয়া রসিক তাহাতে ঘা দিয়াছে কি দেয়
দিল; কুড়ল কাড়িয়া লইয়া কহিল, শালা, একি তোর বাপের গাছ আছে যে কাটতে লেগেছিস?
রসিক গালে হাত বুলাইতে লাগিল, কাগালী কীদ-কাঁদ হইয়া বলিল, বাঃ, এ যে আমার মায়ের
হাতে-পোতা গাছ, দারোয়ানজী | বাবাকে খামোকা তুমি মারলে কেন?

হিন্দুস্থানী দারোয়ান তাহাকেও একটা অসশ্রাব্য গালি দিয়া মারিতে গেল, কিন্তু সে নাকি তাহার
জননীর মৃতদেহ স্পর্শ করিয়া বসিয়াছিল, তাই অশৌচের ভয়ে তাহার গায়ে হাত দিল না। হাকাহাকিতে
একটা ভিড় জমিয়া উঠিল, কেহই অস্বীকার করিল না যে বিনা অনুমতিতে রসিকের গাছ কাটিতে
যাওয়াটা ভালো হয় নাই। তাহারাই আবার দারোয়ানজীর হাতে-পায়ে পড়িতে লাগিল, তিনি অনুগ্বহ
করিয়া যেন একটা হুকুম দেন। কারণ, অসুখের সময় যে-কেহ দেখিতে আসিয়াছে কাঙালীর মার
দারোয়ান ভুলিবার পাত্র নহে, সে হাত-মুখ বাড়িয়া জানাইল, এ-সকল চালাকি তাহার কাছে খাটিবে না।
জমিদার স্থানীয় লোক নহেন; গ্রামে তাহার একটা কাছারি আছে, গোমস্তা অধর রায় তাহার কর্তা ।
লোকপ্তলো যখন হিন্দুস্থানিটার কাছে ব্যর্থ অনুনয়-বিনয় করিতে লাগিল, কাঙালী উর্ধ্বশ্বাসে দৌড়িয়া
একেবারে কাছারি- বাড়িতে আসিয়া উপস্থিত হইল । সে লোকের মুখে মুখে শুনিয়াছিল, পিয়াদারা ঘুষ
লয়, তাহার নিশ্চয় বিশ্বাস হইল অতবড় অসঙ্গত অত্যাচারের কথা যদি কর্তার গোচর করিতে পারে ত
ইহার প্রতিবিধান না হইয়াই পারে না। হায় রে অনভিজ্ঞ! বাংলাদেশের জমিদার ও তাহার কর্মচারীকে
সে চিনিত না। সদ্যমাতৃহীন বালক শোকে ও উত্তেজনায় উদভ্রান্ত হইয়া একেবারে উপরে উঠিয়া
আসিয়াছিল, অধর রায় সেইমাত্র সন্ধ্যাহিক ও যৎসামান্য জলযোগান্তে বাহিরে আসিয়াছিলেন,
বিস্মিত ও ক্রুদ্ধ হইয়া কহিলেন, কে রে?

আমি কাঙালী ৷ দারোয়ানজী আমার বাবাকে মেরেছে।

কাঙালী কহিল, না বাবুমশায়, বাবা গাছ কাটতেছিল,-আমার মা মরেচে-বলিতে বলিতে সে কান্না
আর চাপিতে পারিল না।

কিছু ছুঁইয়া ফেলিল নাকি! ধমক দিয়া বলিলেন, মা মরেচে ত যা নীচে নেবে দীড়া। ওরে কে আছিস
রে, এখানে একটু গোবরজল ছড়িয়ে দে ! কি জাতের ছেলে তুই?

কাঙালী সভয়ে প্রাঙ্গণে নামিয়া দীড়াইয়া কহিল, আমরা দুলে ।

অধর কহিলেন, দুলে ! দুলের মড়ার কাঠ কি হবে শুনি?

কাঙালী বলিল, মা যে আমাকে আগুন দিতে বলে গেছে! তুমি জিজ্ঞেস কর না বাবুমশায়, মা যে

সবাইকে বলে গেছে, সকলে শুনেছে যে! মায়ের কথা বলিতে গিয়া তাহার অনুক্ষণের সমস্ত অনুরোধ
উপরোধ মুহূর্তে স্মরণ হইয়া কণ্ঠ যেন তাহার কান্নায় ফাটিয়া পড়িতে চাহিল।

অধর কহিলেন, মাকে পোড়াবি ত গাছের দাম পাঁচটা টাকা আন্‌ গে । পারবি?

কাঙালী জানিত তাহা অসম্ভব । তাহার উত্তরীয় কিনিবার মূল্যস্বরূপ তাহার ভাত খাইবার পিতলের
কীসিটি বিন্দির পিসি একটি টাকায় বাধা দিতে গিয়াছে সে চোখে দেখিয়া আসিয়াছে, সে ঘাড় নাড়িল,
বলিল, না।

অধর মুখখানা অত্যন্ত বিকৃত করিয়া কহিলেন, না ত, মাকে নিয়ে নদীর চড়ায় পুতে ফেল গে যা।
কার বাবার গাছে তোর বাপ কুড়ুল ঠেকাতে যায়-পাজি, হতভাগা, নচ্ছার !

কাঙালী বলিল, সে যে আমাদের উঠানের গাছ বাবুমশায়! সে যে আমার মায়ের হাতে পৌতা গাছ।

পাড়ে আসিয়া গলাধাক্কা দিল, এবং এমন কথা উচ্চারণ করিল যাহা কেবল জমিদারের কর্মচারীরাই পারে ।
কাঙালী ধুলা ঝাড়িয়া উঠিয়া দাঁড়াইল, তার পরে ধীরে ধীরে বাহির হইয়া গেল। কেন সে যে মার
খাইল, কি তাহার অপরাধ, ছেলেটা ভাবিয়াই পাইল না। গোমস্তার নির্বিকার চিত্তে দাগ পর্যন্ত পড়ি
ল না। পড়িলে এ চাকরি তাহার জুটিত না। কহিলেন, পরেশ, দেখ ত হে, এ ব্যাটার খাজনা বাকি
পড়েছে কি না। থাকে ত জাল-টাল কিছু একটা কেড়ে এনে যেন রেখে দেয়,-হারামজাদা পালাতে
পারে।

মুখুষ্ে-বাড়িতে শ্রাদ্ধের দিন-মাঝে কেবল একটা দিন মাত্র বাকি। সমারোহের আয়োজন গৃহিণীর
উপযুক্ত করিয়াই হইতেছে। বৃদ্ধ ঠাকুরদাস নিজে তন্ত্ীাবধান করিয়া ফিরিতেছিলেন, কাঙালী আসিয়া
তাঁহার সম্মুখে দাঁড়াইল, কহিল, ঠাকুরমশাই, আমার মা মরে গেছে।

তুই কে? কি চাস তুই?

আমি কাঙালী। মা বলে গেছে তেনাকে আগুন দিতে ।

তাদি গেনা।

কাছারির ব্যাপারটা ইতিমধ্যেই মুখে মুখে প্রচারিত হইয়া পড়িয়াছিল, একজন কহিল, ও বোধ হয়
একটা গাছ চায় ।-এই বলিয়া সে ঘটনাটা প্রকাশ করিয়া কহিল।

মুখুষ্যে বিস্মিত ও বিরক্ত হইয়া কহিলেন, শোন আবদার । আমারই কত কাঠের দরকার,-কাল বাদে
পরশু কাজ । যা যা, এখানে কিছু হবে না-এখানে কিছু হবে না। এই বলিয়া অন্যত্র প্রস্থান করিলেন ।

পোড়ায় রে? যা, মুখে একটু নুড়ো জেলে দিয়ে নদীর চড়ায় মাটি দে গে।

মুখোপাধ্যায় মহাশয়ের বড় ছেলে ব্যস্তসমস্তভাবে এই পথে কোথায় যাইতেছিলেন, তিনি কান খাড়া

কাঙালী আর প্রার্থনা করিল না। এই ঘণ্টা-দুয়েকের অভিজ্ঞতায় সংসারে সে যেন একেবারে বুড়া



নদীর চরে গর্ত খুঁড়িয়া অভাগীকে শোয়ান হইল । রাখালের মা কাঙালীর হাতে একটা খড়ের আঁটি
মিলিয়া মাটি চাপা দিয়া কাঙালীর মায়ের শেষ চিহ্ন বিলুপ্ত করিয়া দিল ।

সবাই সকল কাজে ব্যস্ত,_শুধু সেই পোড়া খড়ের আঁটি হইতে যে স্বল্প ধুয়াটুকু ঘুরিয়া ঘুরিয়া
আকাশে উঠিতেছিল, তাহারই প্রতি পলকহীন চক্ষু পাতিয়া কাঙালী উর্্বদষ্টে স্তব্ধ হইয়া চাহিয়া রহিল।

---

### 📚 শব্দার্থ ও টীকা : মুখুয্যে - মুখোপাধ্যায় পদবীর কথ্যরূপ। বর্ধীয়সী - অতি বৃদ্ধ, সকলের মধ্যে বয়সে
বড়, স্ত্রীবাচক শব্দ হিসেবে ব্যবহত। সঙ্গতিপন্ন - অর্থ-সম্পদের অধিকারী। অন্ত্েষ্টিক্রিয়া _ মৃত ব্যক্তির

সৎকার, মৃত্যের জন্য অন্তিম বা শেষ অনুষ্ঠান। সগ্য স্বর্গ শব্দের কথ্যরূপ । অন্তরীক্ষ - আকাশ, গগন।
তুক্তাবশেষ - ভোজন বা খাওয়ার পরে পাতে যা পড়ে থাকে। প্রসন্ন - সন্তুষ্ট, খুশি। প্রসন্নমুখ _ খুশি ভরা
মুখ। ক্রোড় - কোল। শশব্যস্ত - খরগোশ বা শশকের মতো ব্যস্ত। তেনার - তার, তার। দুলে -পালকি
বহনকারী হিন্দু সম্প্রদায়বিশেষ, নীচু জাতের মানুষ বলে অভিহিত। ইন্দ্রজীল _ জাদুবিদ্যা, এখানে গল্পের
মাধ্যমে মুগ্ধ বা মোহিত করে রাখার ক্ষমতাকে বোঝানো হয়েছে। রোমাঞ্চ - শিহরণ, অনুভূতির আধিক্যে
গায়ের লোম দীঁড়িয়ে যাওয়া। ভগ্নিকষ্ঠ - বিকৃত স্বর, এখানে অতি আবেগে কাঙালীর ভাঙা বা বিকৃত
স্বরে কথা বলা বোঝানো হয়েছে। প্রণামী-পুরোহিত বা দেব-দেবীকে দেওয়া সালামি। এখানে কবিরাজকে
চিকিৎসা ফি হিসেবে দেওয়া টাকা বোঝানো হয়েছে। মুষ্টিযোগ - টোটকা চিকিৎসা। গেঁটে কড়ি -
কীটাযুক্ত শামুক জাতীয় প্রাণি। নিস্তব্ধ - নিশ্চল, নিঃসাড় । নির্বাক। হরিধ্বনি- হরি নামের ধ্বনি। হিন্দু
বলে। সংস্কার _ বিশ্বাস, ঝৌক, আজন্ম লালিত ধারণা। অশন - খাদ্যদ্রব্য, আহারের বন্তু। সন্ধ্যাহ্চিক -

