### 📝 পাঠ-পরিচিতি : সুকুমার সেন সম্পাদিত “শরৎ সাহিত্যসমগ'” গ্রন্থের প্রথম খণ্ড থেকে 'অভাগীর স্বর্গ"
নামক গল্পটি সংকলন করা হয়েছে। গরিব-দুখী নীচু শ্রেণির ছেলে কাঙালী । তার মা অভাগী । প্রতিবেশী
উচু জাতের বাড়ির গৃহকন্রীর মৃত্যুর পর সৎকারের দৃশ্য দেখে অভাগীর ভেতরকার ভাবানুভূতি
প্রকাশের মাধ্যমে শুরু হয় এ গল্প। মৃতের শবযাত্রার আড়ম্বরতা ও সৎকারের ব্যাপকতা দেখে অভাগীও
নিজের মৃত্যু মুহূর্তের স্বগ্ন দেখে। চন্দন, সিঁদুর, আলতা, মালা, ঘৃত, মধু, ধূপ, ধুনা, অগ্নির ধোঁয়ায়
মুখুষ্যে বাড়ির গিনি স্বর্ণে গমন করেছেন। দুখিনী অভাগীও ভাবে তার মৃত্যুর সময় স্বামীর পায়ের
ধুলি নিয়ে মৃত্যু শেষে পুত্র মুখাগ্সি করলে সেও স্বর্ণে যাবে । মৃত্যুর সময় কাঙালী তার বাবাকে হাজির
করতে পারলেও পারেনি কাঠের অভাবে মায়ের সৎকার করতে । “অভাগীর স্বর্গ' গল্পে শরৎচন্দ্র
চট্টোপাধ্যায় অমানবিক জাতিভেদ প্রথা এবং জমিদারি ব্যবস্থার শোষণ-নির্ধাতনের ছবি এঁকেছেন । এ
গল্প জাতি, ধর্ম, বর্ণ ও শ্রেণি নিবি শেষে মানবিক হওয়ার শিক্ষা দেয়।

কর্ম-অনুশীলন

১. তোমার দেখা ধনী পরিবারের কারো মৃত্যু ও গরিব পরিবারের কারো মৃত্যুর তুলনামূলক বিবরণ দাও।

