### ❓ পাঠভিত্তিক প্রশ্ন ও উত্তর (Comprehension Q&A)

> ❓ **প্রশ্ন: ‘নিরীহ বাঙালি’ প্রবন্ধে রোকেয়া সাখাওয়াত হোসেন বাঙালির চরিত্রের কোন দুর্বলতা নির্দেশ করেছেন?**
> 💡 **উত্তর:** বাঙালির অতিরিক্ত অলসতা, ভাবালুতা, শ্রমবিমুখতা এবং প্রতিকূলতার বিরুদ্ধে দাঁড়াতে না পারার কাপুরুষোচিত দুর্বলতাকে রোকেয়া তীক্ষ্ণ ব্যঙ্গের সাথে নির্দেশ করেছেন।

> ❓ **প্রশ্ন: বাঙালিকে কেন আত্মসচেতন ও কর্মোদ্যমী হতে হবে?**
> 💡 **উত্তর:** জাতি হিসেবে মাথা তুলে দাঁড়াতে হলে অলস আরামপ্রিয়তা ও দাসত্বসুলভ মনোভাব ত্যাগ করে আধুনিক শিক্ষা ও কঠোর পরিশ্রমে আত্মনিয়োগ করতে হবে।
