কিংবা ভারত উপমহাদেশের বাইরে সিংহল, সুমাত্রা, যাভা, কম্বোডিয়া প্রভৃতি স্থানে এমনিভাবে
প্রচলিত আছে। হয়তো এশিয়ার বাইরে ইউরোপখণ্ডে লিখোনিয়া কিংবা ওয়েলসের কোনো পল্লিরমণী
এখনও হুবহু বা কিছু রূপান্তরিতভাবে সেই উপকথাগুলো তার ছেলেপুলে বা নাতি-পোতাকে
শোনাচ্ছে। কে আছে এই উপকথাগুলো সংগ্রহ করে তাদের অবশ্যস্তাবী ধ্বংসের হাত থেকে রক্ষা
