হয়। দীনেশচন্দ্র সেনের মৌলিক গ্রন্থগুলোর মধ্যে রামায়ণী কথা, বৃহত্ব্গ, বেহুলা, ফুল্পরা, জড়ভরত
ইত্যাদি উল্লেখযোগ্য । ১৯৩৯ খিষ্টাব্দে তিনি পরলোকগমন করেন। রোমী রোলী- (1২01091)
7২0118070) ফরাসি দেশের কালজয়ী সাহিত্যিক ও দার্শনিক ।রোমী রোলার জন্ম ২৯শে জানুয়ারি
১৮৬৬ খিষ্টাব্দে। 'জী ক্রিস্তফ' উপন্যাস তার অমূল্য কীর্তি । এগ্রন্থের জন্য তিনি ১৯১৫ খিিষ্টাব্দে সাহিত্যে
