### 📝 পাঠ-পরিচিতি : ১৯৩৮ খিষ্টাব্দে কিশোরগঞ্জ জেলায় "পূর্ব ময়মনসিংহ সাহিত্য সম্মিলনী'র
একাদশ অধিবেশনে ডক্টর মুহম্মদ শহীদুল্লাহ সভাপতিত্ব করেন। এ সম্মেলনে সভাপতি হিসেবে তিনি
যে অভিভাষণ দেন, তারই পুনর্লিখিত রূপ এই 'পল্লিসাহিত্য” প্রবন্ধটি । আলোচ্য প্রবন্ধে ডক্টর মুহম্মদ
শহীদুল্লাহ বাংলার পল্লিসাহিত্যের বিশেষ কয়েকটি দিক সম্পর্কে আলোচনা করেছেন। লেখক এই
প্রসঙ্গে বলেছেন যে, একদিন এক বিরাট পল্লিসাহিত্য বাংলাদেশে ছিল, আজ উপযুক্ত গবেষক এবং
আগ্রহী সাহিত্যিকদের উদ্যোগ ও চেষ্টায় সেই সম্পদপ্ডলো সংগ্রহ করা নিতান্ত প্রয়োজন ।
