# ৯ম অধ্যায়: উদ্যম ও পরিশ্রম (মোহাম্মদ লুৎফর রহমান)

**বাংলা সাহিত্য • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*গদ্য বিভাগ — রচয়িতা: মোহাম্মদ লুৎফর রহমান*

---

### ✍️ লেখক-পরিচিতি
> লেখক-পরিচিতি: মোহাম্মদ লুৎফর রহমান ১৮৮৯ খিষ্টাব্দে মাগুরা জেলার পারনান্দুয়ালী গ্রামে মাতৃলালয়ে
জনুগ্রহণ করেন। তাঁর পৈতৃক নিবাস যশোর জেলার হাজীগ্রামে | তিনি প্রথমে শিক্ষক এবং পরে
হোমিওপ্যাথ ডাক্তার হিসেবে জীবিকা নির্বাহ করেন। তিনি ডাক্তার লুৎফর রহমান নামে পরিচিত
ছিলেন। নারী সমাজের উন্নতির জন্য নারীতীর্থ নামে সেবা প্রতিষ্ঠান গঠন এবং নারীশক্তি নামে একটি
পত্রিকা প্রকাশ করেছিলেন । তিনি চিন্তাশীল ও যুক্তিবাদী প্রাবন্ধিক হিসেবে খ্যাত হয়েছিলেন । তাঁর প্রবন্ধ
সহজবোধ্য কিন্তু ভাবগন্ভীর । তিনি মহৎ জীবনের লক্ষ্যে সাহিত্যের মাধ্যমে মহৎ চিন্তাচেতনায় মানুষকে
উদ্বু্দ করেছেন । গভীর জীবনবোধ , মানবিক মূল্যবোধ এবং আত্মসম্মান ও মর্যাদার প্রতি সূক্ষ্ম বিশ্লেষণী
প্রীতি উপহার প্রভৃতি তাঁর উল্লেখযোগ্য গ্রন্থ। প্রবন্ধ ছাড়াও তিনি কবিতা, উপন্যাস ও ছোটদের বই রচনা
করেছেন । ১৯৩৬ খিষ্টাব্দে তিনি পরলোকগমন করেন ।

---

## 📖 মূল পাঠ (গদ্য)

উদ্যম ও পরিশ্রম
মোহাম্মদ লুৎফর রহমান



চাকরি করা উত্তম, যখন তা হয় জাতির সেবা- যখন তাতে মর্যাদা ও ব্যক্তি নষ্ট হয় না। যখন
জীবন ধারণের সম্বল হয়ে পড়ে চাকরি-যখন সেটাকে দেশ-সেবা বলে মনে হয় না, তখন তা কোরো না।
সত্য ও আইন অপেক্ষা উপরিস্থ কর্মচারীকে যদি বেশি মানতে হয়, তা হলে সরে পড়। প্রভুর সামনে
সঙ্গতি না থাকে- তাহলে বুঝব চাকরি করে তুমি পাপ করেছ।

মনের স্বাধীনতাকে রক্ষা করতে না পারলে তোমাতে ও পশুতে প্রভেদ থাকবে না- জীবন তোমার
মিথ্যা হবে। স্বাধীন হৃদয়, সত্যের সেবক কামার হও, সেও ভালো । নিজকে যন্ত্র করে ফেলো না।

সৎ, জ্ঞানী ও মহৎ যিনি, তিনি নিজকে ব্যক্তিত্হীন করতে ভয়ংকর লজ্জা বোধ করেন। তিনি
তাতে পাপ বোধ করেন।

চাকরি করে অন্যায় পয়সায় ধনী হবার লোভ রাখ? তোমার চেয়ে মুদি ভালো । মুদির পয়সা পবিত্র ।
অনেক যুবক থাকতে পারে, যারা মনে করে কোনোরকম একটা চাকরি সংগ্রহ করে সমাজের ভেতরে
আসন প্রতিষ্ঠা করতে পারলেই হলো । চুরির সাহায্যেই হোক বা অসৎ উপায় অবলম্বন করেই হোক,
ক্ষতি নেই।

চরিত্র তোমার নিষ্বলঙ্ক- সামান্য কাজ করে পয়সা উপায় কর, তাতে জাত যাবে না। চুরি অন্যায়ের
সাহায্যে যে বাচতে চেষ্টা করে, তারই জাত যায়, অসৎ উপায়ে আয় কোরো না, মিথ্যার আশ্রয় নিও
না। লোককে কায়দায় ফেলে অর্থ সংগ্রহ করতে তুমি ঘৃণা বোধ কোরো ।

ইউরোপের জ্ঞানগুরু প্লেটো মিসর ভ্রমণকালে মাথায় করে তেল বেচে রাস্তা-খরচ জোগাড় করতেন।
যে কুঁড়ে,আলসে, ঘুষখোর ও চোর, সেই হীন। ব্যবসা বা ছোটো স্বাধীন কাজে মানুষ হীন হয় না_
হীন হয় মিথ্যা চতুরতা ও প্রবঞ্চনায়। পাছে জাত যায়, সম্মান নষ্ট হয়- এই ভয়ে পরের গলগ্রহ
হয়ে মাসের পর মাস কাটিয়ে দিচ্ছ? সম্মান কোথায়, তা তুমি টের পাওনি?

সৎ উপায়ে যে পয়সা উপায় করা যায় তাতে তোমার আত্মার পতন হবে না। তোমার আত্মার পতন
হবে আলস্যে ও অসাধুতায় ৷ তোমারই স্পর্শে কাজ গৌরবময় হবে ।

আমাদের দেশের লোক যেমন আজকাল বিলেতে যায় এককালে তেমনি করে বিলেতের লোক গ্রিস ভ্রমণে যেত।

বিলেত-ফেরত লোককে কেউ ইট টেনে বা কুলির কাজ করে পয়সা উপায় করতে দেখেছে?

বিলেতের এক পপ্তিত দেশভ্রমণ দ্বারা অগাধ জ্ঞান অর্জন করেছিলেন- গ্রিকদেশ থেকে ফিরে এসে তিনি
আরম্ভ করলেন এমন কাজ, যা তুমি আমি করতে লঙ্জাবোধ করব । তাতে কি তার জাত গিয়েছিল?
যার মধ্যে জ্ঞান ও গুণ আছে, সে কয়দিন নিচে পড়ে থাকে? লোকে তীকে সম্মান করে উপরে টেনে
তোলেই।

কাজে মানুষের জাত যায় না- এটা বিশ্বাস করতে হবে । কাজহীন হও এ সময় যখন কাজের ভেতর

বিশ্ব-সভ্যতার এত দান তুমি ভোগ কর এসব কী করে হলো? হাতের সাহায্যে নয় কি? কাজকামকে
খেলো মনে করলে চলবে না। মিস্ত্রির হাতুড়ির আঘাত, কামারের কপালের ঘাম, কুলির কোদালকে
শ্রদ্ধার চোখে দেখো ।

অনেকে বলে, তাদের জন্য কোনো কাজ নেই। যে কাজই তারা করুক, যে দিকেই তারা হাঁটুক-
কেবল ব্যর্থতা আর ব্যর্থতা! মূর্খ যারা তারাই এ কথা বলে। তাদের এ ব্যর্থতার জন্য তারা

তিনি কারও কাছে কোনো হাত পাতেননি। এক বন্ধু তাকে এক সময় এক জোড়া জুতো দিয়েছিলেন ।
অপমানবোধ করে তিনি সে জুতো পথে ফেলে দিয়েছিলেন । উদ্যম, পরিশ্রম ও চেষ্টার সামনে সব
বাধাই পানি হয়ে যায়। এ গুণ যার মধ্যে আছে, যে ব্যক্তি পরিশ্রমী, তার দুঃখ নেই। জনসনকে অনেক
সময় রাত্রিতে না খেয়ে শুয়ে থাকতে হতো, তাতে তিনি কোনোদিন ব্যথিত বা হতাশ হননি । বাধাকে
চূর্ণ করে বীরপুরুষের মতো তিনি যে কীর্তি রেখে গিয়েছেন,তা অনেক দেশের অনেক পণ্তিতই পারবেন না।

গুণ থাকলেও চেষ্টা না করলে জগতে প্রতিষ্ঠা লাভ করা যায় না। আরভিং সাহেব বলেছেন, চুপ
করে বসে থাকলে কাজ হবে না। চেষ্টা কর, নড়াচড়া কর, এমন কি কিছু-নাড়, ভেতর কিছু ফলাতে
পারবে । কুকুরের মতো চিৎকার কর, সিংহ হয়েও ঘুমিয়ে থাকলে কী লাভ?

পরীক্ষায় কৃতকার্য হয়েছ, তারপর মনে হচ্ছে তোমার মুল্য এক পয়সা নয়। জিজ্ঞাসা করি, কেন?

তোমার এই মর্মবেদনা ও দুঃখের কারণ তুমি মুর্খ । মানুষ বালিতে সোনা ফলাতে পারে, এ তুমি
বিশ্বাস কর না? তুমি কুঁড়ে, তোমার উদ্যম নেই, তুমি একটা আত্মপ্রত্যয়হীন অভাগা ।

কাজ ছোটো হোক, বড়ো হোক, প্রাণ-মন দিয়ে করবে। মূল্যহীন বন্ধুগণের লজ্জায় কাজকে ঘৃণা

ফক্স সাহেবকে এক সময় এক ভদ্রলোক বলেছিলেন, আপনার লেখা ভালো নয়। কাজের চারুতার
প্রতি তার এত নজর ছিল যে, তিনি সেই দিন থেকে স্কুলের বালকের ন্যায় লেখা আরন্ত করলেন এবং
অল্পকালের মধ্যে তার লেখা চমৎকার হয়ে গেল ।

