### ✍️ লেখক-পরিচিতি
> লেখক-পরিচিতি: হুগলি জেলার শ্রীরামপুরছ্থ বড়তাজপুর গ্রামে ১৮৯০খিষ্টাব্দের ৪ঠা সেপ্টেম্বর এস.
ওয়াজেদ আলি জন্গ্রহণ করেন । শিলং-এর মোখার হাইস্কুল থেকে স্বর্ণপদকসহ এন্টরান্স পাশের পর তিনি
আলীগড় কলেজ থেকে আইএ এবং ১৯১০ খিষ্টাব্দ এলাহাবাদ বিশ্ববিদ্যালয় থেকে বিএ পাশ করেন।
১৯১৫ সালে কেন্ত্িজ বিশ্ববিদ্যালয় থেকে বার আ্যাট-ল ডিগ্রি লাভ করে তিনি কলকাতা হাইকোর্টে আইন
ব্যবসা শুরু করেন। ১৯২৩ সালে তিনি কলকাতা প্রেসিডেন্সি ম্যাজিষ্টেট নিযুক্ত হন। ১৯২৫ সালে তিনি
বঙ্গীয় মুসলমান সাহিত্য সমিতির সভাপতি নির্বাচিত হন। সত্য ও সুন্দরের সাধনায়, নীতিজ্ঞান, ধর্ম বোধ
ও প্রেমের শাশ্বত মহিমায় মার্জিত রুচি ও পরিচ্ছন্ন রসবোধে তাঁর সাহিত্যকর্ম সমৃদ্ধ । তাঁর উল্লেখযোগ্য
প্রবন্ধ গ্রন্থ: জীবনের শিল্প (১৯৪১), প্রাচ্য ও প্রতীচ্য (১৯৪৩), ভবিষ্যতের বাঙালি (১৯৪৩); গল্পগ্রন্থ:
গুলদাস্তা (১৯২৭), মাশুকের দরবার (১৯৩০), ভ্রমণকাহিনী: মোটরযোগে রাঁচির সফর (১৯৪৯),
পশ্চিম ভারত (১৩৫৫) । ১৯৫১ খিষ্টাব্দের ১০ই জুন তিনি কলকাতায় মৃত্যুবরণ করেন |

