### ✍️ মূল পাঠ্যবইয়ের সৃজনশীল প্রশ্ন

বিছানায় গায়ে দিয়ে শোওয়ার জন্য একটি সামগ্রী- সেটা তো সুন্দর-অসুন্দর হওয়ার প্রয়োজন
নেই। কিন্তু এই প্রয়োজনের জিনিসকে সুই আর রঙিন সুতা দিয়ে অপূর্ব নকশা করে সাজিয়েছেন
গায়ের বধুরা। নকশিকীথা দেখলেই সুন্দর লাগে, জিনিসটির প্রয়োজনের কথা মনেই পড়ে না। এ
শরীরকে তৃপ্ত করল আর- প্রয়োজনের বাইরে যে সুন্দর তা মনকে তৃপ্ত করল ।'

ক. “সমবায়িক' শব্দের অর্থ কী?
গ. উদ্দীপকে “জীবনে শিল্পের স্থান" প্রবন্ধে ফুটে ওঠা দিকটি ব্যাখ্যা করো ।

ঘ. “উল্লিখিত ফুটে ওঠা দিকটি “জীবনে শিল্পের স্থান” প্রবন্ধের আংশিক প্রতিফলন মাত্র ”-
মন্তব্যটির যথার্থতা নির্পণ করো।

