বিভূতিভূষণ বন্দ্যোপাধ্যায়



একটা ছোটো টিনের বাক্স আছে, সেটার ডালা ভাঙা । বাক্সের সমুদয় সম্পত্তি সে উপুড় করিয়া মেঝেতে
ঢালিয়াছে। একটা রং-ওঠা কাঠের ঘোড়া, চার পয়সা দামের একটা টোল্-খাওয়া টিনের ভেঁপু-বাঁশি,
গোটাকতক কড়ি। এগুলি সে মায়ের অজ্ঞাতসারে লক্ষ্মীপূজার কড়ির চুপড়ি হইতে খুলিয়া লইয়াছিল ও
আনিয়াছিল, কিছু তাহাকে দিয়াছে, কিছু নিজের পুতুলের বাক্সে রাখিয়া দিয়াছে। খানকতক খাপরার
কুচি। গঙ্গা-যমুনা খেলিতে এই খাপরাগুলির লক্ষ্য অব্যর্থ বলিয়া বিশ্বাস হওয়ায় সে এগুলি সযত্তে
বাক্সে রাখিয়া দিয়াছে, এগুলি তাহার মহামূল্যবান সম্পত্তি এতগুলি জিনিসের মধ্যে সবেসে টিনের
বাশিটা কয়েকবার বাজাইয়া সেটির সম্বন্ধে বিগত কৌতৃহল হইয়া তাহাকে একপাশে রাখিয়া দিয়াছে।
কাঠের ঘোড়া নাড়াচাড়া করা হইয়া গিয়াছে। সেটিও একপাশে পিজরাপোলের আসামির ন্যায়
পড়িয়া আছে। বর্তমানে সে গঙ্গা-যমুনা খেলিবার খাপরাগ্ুলিকে হাতে লইয়া মনে মনে দাওয়ার
উপর গঙ্গা-যমুনার ঘর আঁকা কল্পনা করিয়া চোখ বুজিয়া খাপরা ছুঁইয়া দেখিতেছে তাক ঠিক
হইতেছে কি না!

এমন সময়ে তাহার দিদি দুর্গা উঠানের কীঠালতলা হইতে ডাকিল-অপু_- ও অপু-। সে এতক্ষণ
বাড়ি ছিল না, কোথা হইতে এইমাত্র আসিল । তাহার স্বর একটু সতর্কতা মিশ্রিত। মানুষের গলার
আওয়াজ পাইয়া অপু কলের পুতুলের মতো লক্ষ্মীর চুপড়ির কড়িগুলি তাড়াতাড়ি লুকাইয়া ফেলিল।
পরে বলিল- কি রে দিদি?

দুর্গা হাত নাড়িয়া ডাকিল- আয় এদিকে- শোন্‌_

দুর্গার বয়স দশ-এগারো বৎসর হইল। গড়ন পাতলা পাতলা, রং অপুর মতো অতটা ফর্সা নয়, একটু
চাপা । হাতে কাচের চুড়ি, পরনে ময়লা কাপড়, মাথার চুল রুক্ষ_ বাতাসে উড়িতেছে, মুখের গড়ন
মন্দ নয়, অপুর মতো চোখগুলি বেশ ডাগর ডাগর। অপু রোয়াক হইতে নামিয়া কাছে গেল, বলিল,-কে রে?

দুর্গার হাতে একটা নারিকেলের মালা! সেটা সে নিচু করিয়া দেখাইল, কতকগুলি কচি আম কাটা।
সুর নিচু করিয়া বলিল- মা ঘাট থেকে আসে নি তো?

অপু ঘাড় নাড়িয়া বলিল- উহু-

দুর্গা চুপিচুপি বলিল - একটু তেল আর একটু নুন নিয়ে আসতে পারিস? আমের কুশি জারাবো _
অপু আহ্রাদের সহিত বলিয়া উঠিল _ কোথায় পেলি রে দিদি?

দুর্গা বলিল-পটলিদের বাগানে সিঁদুরকৌটোর তলায় পড়ে ছিল - আন্‌ দিকি একটু নুন আর তেল!
অপু দিদির দিকে চাহিয়া বলিল _ তেলের ভাড় ছুলে মা মারবে যে? আমার কাপড় যে বাসি?

_ তুই যা না শিগগিরি করে, মা'র আসতে এখন ঢের দেরি-ক্ষার কাচতে গিয়েচে শিগগির যা-

অপু বলিল- নারকোলের মালাটা আমায় দে। ওতে ঢেলে নিয়ে আসবো- তুই খিড়কি দোরে গিয়ে
দ্যাখ মা আসচে কি না।

দুর্গা নিয়নস্বরে বলিল_ তেলটেল যেন মেঝেতে ঢালিসনে, সাবধানে নিবি, নইলে মা টের পাবে-
তুই তো একটা হাবা ছেলে-

অপু বাড়ি মধ্য হইতে বাহির হইয়া আসিলে দুর্গা তাহার হাত হইতে মালা লইয়া আমগুলি বেশ
করিয়া মাখিল,_ বলিল, নে হাত পাত।

_ তুই অতগ্তলো খাবি দিদি?

_ অতগুলি বুঝি হলো? এই তো- ভারি বেশি- যা, আচ্ছা নে আর দু"খানা- বাঃ, দেখতে বেশ
হয়েচে রে, একটা লঙ্কা আনতে পারিস? আর একখানা দেবো তা হলে-

_ লঙ্কা কী করে পাড়বো দিদি? মা যে তক্তার ওপর রেখে দ্যায়, আমি যে নাগাল পাই নে?

_ তবে থাকগে যাক্‌ - আবার ওবেলা আনবো এখন-পটলিদের ডোবার ধারের আমগাছটায় গুটি যা
দুর্গাদের বাড়ির চারিদিকেই জঙ্গল। হরিহর রায়ের জ্ঞাতি-ভ্রাতা নীলমণি রায় সম্প্রতি গত বৎসর মারা
জঙ্গলাবৃত হইয়া পড়িয়া আছে। নিকটে আর কোনো লোকের বাড়ি নাই । পাচ মিনিটের পথ গেলে তবে
ভুবন মুখুয্ের বাড়ি।

হরিহরের বাড়িটাও অনেকদিন হইয়া গেল মেরামত হয় নাই, সামনের দিকের রোয়াক ভাঙা, ফাটলে
বন-বিছুটির ও কালমেঘ গাছের বন গজাইয়াছে- ঘরের দোর-জানালার কপাট সব ভাঙা, নারিকেলের
দড়ি দিয়া গরাদের সঙ্গে বাধা আছে।

খিড়কি দোর ঝনাৎ করিয়া খুলিবার শব্দ হইল এবং একটু পরেই সর্বজয়ার গলা শুনা গেল-দুগ্গা, ও দুগ্গা-
দুর্গা বলিল-মা ডাকছে, যা দেখে আয়- ওখানা খেয়ে যা- মুখে যে নুনের গুঁড়ো লেগে আছে,মুছে ফ্যাল্‌-



মায়ের ডাক আর একবার কানে গেলেও দুর্গার এখন উত্তর দিবার সুযোগ নাই, মুখ ভর্তি। সে
কীঠালগাছটার কাছে সরিয়া গিয়া গুঁড়ির আড়ালে দীড়াইয়া সেগুলি গোগ্াসে গিলিতে লাগিল। অপু
তাহার পাশে দীড়াইয়া নিজের অংশ প্রাণপণে গিলিতেছিল, কারণ চিবাইয়া খাওয়ার আর সময় নাই।
খাইতে খাইতে দিদির দিকে চাহিয়া সে দোষ সম্বন্ধে সচেতনতাসূচক হাসি হাসিল । দুর্গা খালি মালাটা
এক টান্‌ মারিয়া ভেরেপ্তাকচার বেড়া পার করিয়া নীলমণি রায়ের ভিটার দিকে জঙ্গলের মধ্যে ছঁড়িয়া
দিল। ভাইয়ের দিকে চাহিয়া বলিল- মুখটা মুছে ফ্যাল্‌ না বাদর, নুন লেগে রয়েছে যে ...

পরে দুর্গা নিরীহমুখে বাড়ির মধ্যে টুকিয়া বলিল- কী মা?

-কোথায় বেরুনো হয়েছিল শুনি? একলা নিজে কতদিকে যাবো? সকাল থেকে ক্ষার কেচে গা-
গতর ব্যথা হয়ে গেল, একটুখানি কুটোগাছটা ভেঙে দু খানা করা নেই, কেবল পাড়ায় পাড়ায়
টোটো টোকলা সেধে বেড়াচ্ছেন- সে বাঁদর কোথায়?

অপু আসিয়া বলিল, মা, খিদে পেয়েছে!

-রোসো রোসো, একটুখানি দীড়াও বাপু ... একটুখানি হাপ জিরোতে দ্যাও! তোমাদের রাতদিন
খিদে আর রাতদিন ফাই-ফরমাজ! ও দুগ্গা, দ্যাখ তো বাছুরটা হাক পাড়ছে কেন?

খানিকটা পরে সর্বজয়া রান্নাঘরের দাওয়ায় বঁটি পাতিয়া শসা কাটিতে বসিল। অপু কাছে বসিয়া পড়িয়া
বলিল -আর এট্রু আটা বের করো না মা, মুকে বড্ড লাগে!

দুর্গা নিজের ভাগ হাত পাতিয়া লইয়া সঙ্কুচিত সুরে বলিল- চালভাজা আর নেই মা?

অপু খাইতে খাইতে বলিল- উঃ, চিবনো যায় না। আম খেয়ে দাত টকে-

দুর্গার ভুকুটিমিশ্রিত চোখটেপায় বাধা পাইয়া তাহার কথা অর্ধপথেই বন্ধ হইয়া গেল। তাহার মা
জিজ্ঞাসা করিল, আম কোথায় পেলি?

সত্য কথা প্রকাশ করিতে সাহসী না হইয়া অপু দিদির দিকে জিজ্ঞাসাসূচক দৃষ্টিতে চাহিল। সর্বজয়া
মেয়ের দিকে চাহিয়া বলিল- তুই ফের এখন বেরিয়েছিলি বুঝি?

দুর্গা বিপন্মুখে বলিল- ওকে জিজ্ঞেস করো না? আমি- এই তো এখন কীঠালতলায় দীড়িয়ে-
তুমি যখন ডাক্‌লে তখন তো-

স্বর্ণ গোয়ালিনী গাই দুহিতে আসায় কথাটা চাপা পড়িয়া গেল। তাহার মা বলিল- যা, বাছুরটা
ধরগে যা- ডেকে সারা হোলো- কমলে বাছুর, ও সন্ন, এত বেলা করে এলে কি বাচে? একটু সকাল
করে না এলে এই তেতপ্পর পজ্জন্ত বাছুর বাধা_

দিদির পিছনে পিছনে অপুও দুধ দোয়া দেখিতে গেল। সে বাহির উঠানে পা দিতেই দুর্া হাতার
পিঠে দুম্‌ করিয়া নির্ঘাত এক কিল বসাইয়া দিয়া কহিল- লক্ষ্মীছাড়া বাদর! পরে মুখ ভ্যাঙাইয়া কহিল-
আম খেয়ে দাত টকে গিয়েছে- আবার কোনোদিন আম দেবো খেও-ছাই দেবো-এই ওবেলাই
তোমায়? খেও এখন? হাবা একটা কোথাকার- যদি এতটুকু বুদ্ধি থাকে!

দুপুরের কিছু পরে হরিহর কাজ সারিয়া বাড়ি ফিরিল। সে আজকাল গ্রামের অন্নদা রায়ের বাটীতে
গোমস্তার কাজ করে। জিজ্ঞাসা করিল- অপুকে দেখচি নে?

সর্বজয়া বলিল- অপু তো ঘরে ঘুমুচ্ছে।

_দুগ্গা বুঝি_
_-সে সেই খেয়ে বেরিয়েছে- সে বাড়ি থাকে কখন? দুটো খাওয়ার সঙ্গে যা সম্পর্ক! আবার সেই খিদে
পেলে তবে আসবে- কোথায় কার বাগানে কার আমতলায় জামতলায় ঘুরছে- এই চত্তির মাসের
রোদ্দুরে, ফের দ্যাখো না এই জুরে পড়লো বলে- অত বড় মেয়ে, বলে বোঝাবো কত? কথা শোনে,
না কানে নেয়?

একটু পরে হরিহর খাইতে বসিয়া বলিল- আজ দশঘরায় তাগাদার জন্যে গেছলাম, বুঝলে? একজন
লোক,খুব মাতবর, পাচটা-ছয়টা গোলা বাড়িতে, বেশ পয়সাওয়ালা লোক- আমায় দেখে দপ্তবৎ
করে বনে

দাদাঠাকুর, আমায় চিনতে পাচ্ছেন? আমি বল্লাম- না বাপু, আমি তো কৈ?- বল্পে- আপনার কর্তা
আমাদের গুরুতুল্য লোক, এবার আমরা বাড়িসুদ্ধ মন্তর নেবো ভাবচি- তা আপনি যদি আজ্ঞে করেন,
