### 📚 শব্দার্থ ও টীকা : রোয়াক _ ঘরের সামনের খোলা জায়গা বা বারান্দা। চুপড়ি - ছোটো ঝুড়ি, ক্ষুদ্র
ধামা। নাটাফল - করঞ্া ফল। খাপরার কুচি - কলসি-হাঁড়ি প্রভৃতির ভাঙা অংশ বা টুকরা।
পিজরাপোলের আসামি - খাঁচায় পড়ে থাকা অবহেলিত আসামির মতো অর্থে। দাওয়া - বারান্দা।
? আমের কুসি- কচি আম। জারা -জীর্ণ করা, কুচি কুচি করা অর্থে। বন-বিছুটি - এক প্রকার বুনো গাছ।

কালমেঘ - যকৃতের রোগে উপকারী একপ্রকার তিক্ত স্বাদের গাছ। গরাদ- জানালার শিক।
ভেরেপ্তাকচার বেড়া-এরন্ড বা রেড়ি গাছের বেড়া ৷ কুটোগাছ- তৃণ। রোসো রোসো - থাম থাম।

