### ❓ পাঠভিত্তিক প্রশ্ন ও উত্তর (Comprehension Q&A)

> ❓ **প্রশ্ন: ‘আম-আঁটির ভেঁপু’ গল্পে গ্রামীণ শৈশবের কোন চিত্র ফুটে উঠেছে?**
> 💡 **উত্তর:** অপু ও দুর্গার নিষ্পাপ আনন্দ, চঞ্চলতা, গ্রামীণ প্রকৃতির সাথে তাদের গভীর আত্মিক টান এবং দারিদ্র্যের মধ্যেও অপরিসীম আনন্দের স্পর্শ ফুটে উঠেছে।

> ❓ **প্রশ্ন: দুর্গার চরিত্রটি কীভাবে এক চিরন্তন বাঙালি কিশোরীর প্রতীক হয়ে উঠেছে?**
> 💡 **উত্তর:** প্রকৃতির বনে-বাদাড়ে ফল কুড়ানো, ভাইকে স্নেহ করা এবং সরল আনন্দের মধ্য দিয়ে দুর্গা আবহমান বাংলার শাশ্বত শৈশবের প্রতীক রূপ লাভ করেছে।
