### 📝 পাঠ-পরিচিতি : “মানুষ মুহম্মদ (স.)' প্রবন্ধটি মোহাম্মদ ওয়াজেদ আলী রচিত মরু ভাস্কর গ্রন্থ থেকে
নেওয়া হয়েছে। হজরত মুহম্মদ (স.)-এর মানবিক গুণাবলি এ প্রবন্ধে বিশ্লেষণ করা হয়েছে। হযরত
ছিলেন মানুষের নবি। তাই মানুষের পক্ষে যা আচরণীয় তিনি তারই আদর্শ প্রতিষ্ঠা করে গেছেন।
তিনি বিপুল এশর্য, ক্ষমতা ও মানুষের অগাধ ভালোবাসা ও শ্রদ্ধার মধ্যে থেকেই একজন সাধারণ
মানুষের মতো জীবনযাপন করে গেছেন। ক্ষমতা ও মহত্ব, প্রেম ও দয়া তার অজস্র চারিত্রিক গুণের
মধ্যে প্রধান। তীর সমগ্র জীবন মানব জাতির কল্যাণের জন্য নিয়োজিত ছিল। মানুষের শ্রেষ্ঠ
আদর্শ হিসেবে তিনি তার জীবন রূপায়িত করে তুলেছিলেন। তীর সাধনা, ত্যাগ, কল্যাণচিন্তা ছিল
বিশ্বের সমগ্র মানুষের জন্য অনুকরণীয় । হজরত মুহম্মদ (স.) এর মৃত্যুর পর তার অনুসারীগণের
মধ্যে যে বেদনা ও হতাশা দেখা দিয়েছিল তা প্রশমন করার জন্য হজরত আবুবকর (রো) মহানবি
(স.)-এর জীবনের বৈশিষ্ট্য তুলে ধরে প্রচণ্ড শোককে শান্ত করেন। হজরত মুহম্মদ (স.)-এর
মানবিক গুণাবলি উপস্থাপনের মাধ্যমে এ প্রবন্ধ আমাদের নৈতিক, সৎ ও মানবিক হবার শিক্ষা দেয় ।

কর্ম-অনুশীলন
হজরত মুহম্মদ (স.)-এর চারিত্রিক বৈশিষ্ট্যের একটি তালিকা তৈরি করো ।

