# ১৩তম অধ্যায়: উপেক্ষিত শক্তির উদ্বোধন (কাজী নজরুল ইসলাম)

**বাংলা সাহিত্য • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*গদ্য বিভাগ — রচয়িতা: কাজী নজরুল ইসলাম*

---

### ✍️ লেখক-পরিচিতি
> লেখক-পরিচিতি : কাজী নজরুল ইসলাম ১১ই জ্যৈষ্ঠ, ১৩০৬ বঙ্গাব্দে (২৪ শে মে, ১৮৯৯ খিষ্টাব্দ) ভারতের পশ্চিমবঙ্গের
বর্ধমান জেলার আসানসোল মহকুমার চুরুলিয়া গ্রামে জনুগ্রহণ করেন। ছেলেবেলায় তিনি লেটো গানের দলে
যোগ দেন । পরে বর্ধমান ও ময়মনসিংহের ত্রিশাল থানার দরিরামপুর হাই স্কুলে লেখাপড়া করেন।
১৯১৭ খিষ্টাব্দে তিনি সেনাবাহিনীর বাঙালি পল্টনে যোগ দিয়ে করাচি যান। সেখানেই তার সাহিত্য-জীবনের
সুচনা ঘটে । তার লেখায় তিনি সামাজিক অবিচার ও পরাধীনতার বিরুদ্ধে সোচ্চার হয়েছেন। এজন্য তাকে
“বিদ্রোহী কবি' বলা হয়। বাংলা সাহিত্য জগতে তার আবির্ভাব এক নতুন দিগন্তের উন্মোচন করে । কবিতা,
উপন্যাস, নাটক, ছোটগল্প ও প্রবন্ধ ইত্যাদি সাহিত্যের সকল শাখায় তিনি প্রতিভার স্বাক্ষর রেখেছেন।
তিনি গজল, খেয়াল ও রাগপ্রধান গান রচনা করে খ্যাতি অর্জন করেন। আরবি-ফারসি শব্দের সার্থক ব্যবহার
হারিয়ে ফেলেন। বাংলাদেশ প্রতিষ্ঠার পর অসুস্থ কবিকে ঢাকায় আনা হয় এবং পরে তাকে বাংলাদেশের
নাগরিকত্‌ প্রদান করা হয়। তাকে স্বাধীন বাংলাদেশের জাতীয় কবির মর্যাদায় ভূষিত করা হয়। তার রচিত
কাব্যগুলোর মধ্যে অগিবীণা, বিষের বাঁশি, ছায়ানট, এলয়শিখা, চক্রবাক, সিন্ধৃহিন্দোল বিশেষভাবে উল্লেখযোগ্য ।
বথার দান, রিক্তের বেদন, শিউলিমালা, মৃত্যক্ষধা, কৃহেলিকা ইত্যাদি তার রচিত গল্প ওউপন্যাস। বুগবাণী,
দুদিনের যাত্রী ও রাজবন্দীর জবানবন্দী তার উল্লেখযোগ্য প্রবন্ধগ্রন্থ । ২৯শে আগস্ট, ১৯৭৬ খিষ্টাব্দে কৰি ঢাকার
পি.জি. হাসপাতালে (বর্তমান নাম বাংলাদেশ মেডিক্যাল বিশ্ববিদ্যালয়) শেষ নিঃশ্বাস ত্যাগ করেন। ঢাকা
বিশ্ববিদ্যালয়ে মসজিদ-সংলগ্ন প্রাঙ্গণে তাকে পরিপূর্ণ রাষ্ট্রীয় মর্যাদায় সমাহিত করা হয় |

