### ❓ পাঠভিত্তিক প্রশ্ন ও উত্তর (Comprehension Q&A)

> ❓ **প্রশ্ন: কাজী নজরুল ইসলাম ‘উপেক্ষিত শক্তি’ বলতে কাদের বুঝিয়েছেন?**
> 💡 **উত্তর:** দেশের তথাকথিত নিম্নবর্ণের, খেটে খাওয়া সাধারণ শ্রমজীবী ও কৃষক-মজুর সম্প্রদায়কে নজরুল উপেক্ষিত শক্তি বলেছেন, যাদের শ্রমে দেশ টিকে আছে।

> ❓ **প্রশ্ন: উপেক্ষিত শক্তির উদ্বোধন ছাড়া দেশের মুক্তি সম্ভব নয় কেন?**
> 💡 **উত্তর:** যে দেশের শতকরা নিরানব্বই জন মানুষ অবহেলিত ও শোষিত, তাদের পেছনে ফেলে রেখে মুষ্টিমেয় উচ্চবিত্তের অগ্রগতি দিয়ে কখনোই দেশের সামগ্রিক স্বাধীনতা ও কল্যাণ সম্ভব নয়।
