### ✍️ লেখক-পরিচিতি
> লেখক-পরিচিতি : প্রকৃত নাম বলাইচাদ মুখোপাধ্যায় । বিহারের পূর্ণিয়ার অন্তর্গত মণিহার গ্রামে ১৮৯৯ খিষ্টাব্দের
১৯শে জুলাই তিনি জন্মগ্রহণ করেন। বনফুল পূর্ণিয়ার সাহেবগঞ্জ ইংরেজি উচ্চ বিদ্যালয় থেকে ম্যাট্রিক,
হাজারীবাগের সেন্ট কলম্বাস কলেজ থেকে আইএসসি এবং পাটনা মেডিক্যাল কলেজ থেকে
এমবি পাশ করেন। মেডিক্যাল অফিসার পদে চাকরির মাধ্যমে বনফুলের কর্মজীবন শুরু । ১৯১৮ খিষ্টাব্দে
শনিবারের চিঠি'তে ব্যঙ্গ-কবিতা ও প্যারোডি লিখে তার সাহিত্য অঙ্গনে প্রবেশ। প্রবাসী পত্রিকায় তিনি একপাতা-
আধপাতার গল্প লিখতেন । গল্পগুলো আকারে ক্ষুদ্র, অথচ বক্তব্যে তাৎপর্ষপূর্ণ। তার উল্লেখযোগ্য গল্পগ্রন্থ :
উপাদান তার গল্প ও উপন্যাসে নিপুণভাবে প্রকাশিত হয়েছে। বনফুলের উল্লেখযোগ্য উপন্যাস হলো: তৃণখণ,
কিছুক্ষণ, দ্বৈরথ, জঙ্গম ইত্যাদি । বিভিন্ন পুরস্কারসহ তিনি পদ্মভূষণ উপাধি লাভ করেন । ১৯৭৯ খিষ্টাব্দের ৯ই

ফেকুয়ারি বনফুল কলকাতায় মৃত্যুবরণ করেন |

