### 📝 পাঠ-পরিচিতি : বলাইচাদ মুখোপাধ্যায়ের (বনফুল) অদৃশ্যলোক গ্রন্থের অন্তর্ভূক্ত “নিমগাছ'
গল্প । এই গল্পের সংক্ষিপ্ত অবয়বের মধ্যে লেখক বিপুল বক্তব্য উপস্থাপনে যে দক্ষতার পরিচয় দিয়েছেন
তা বাংলা সাহিত্যে বিরল । নিমগাছের বর্ণনা, এর পাতা, বাকল, ছায়া ইত্যাদির বাহ্যিক উপকারিতা
কবিতার মতো বর্ণনা করা হয়েছে এই গল্পে। কবিরাজ তার চিকিৎসার কাজে, সাধারণ মানুষ
প্রাত্যহিক প্রয়োজনে নিমগাছকে অনবরত ব্যবহার করে থাকে । কিন্তু কেউ এই গাছের সামান্যও
যত্বু নেয় না। একজন কবি একদিন নিমগাছের গুণ ও রূপের প্রশংসা করে । নিমগাছের ভালো লাগে
এ লোককে এবং সে তার সঙ্গে চলে যেতে চায় । কিন্ত মাটির গভীরে তার শিকড় । গাছটি যেতে পারে
না। আসলে গাছ তো চলতে পারে না। এটি একটি প্রতীকী গল্প । প্রকৃতপক্ষে, “নিমগাছ' গল্পটির নিমগাছ
ও সামাজিক গুরুত্ব উপলব্ধি করার ইঙ্গিত দেয় গল্পটি ।

কর্ম-অনুশীলন
১। নিমগাছের গুণাগ্তণের একটি তালিকা তৈরি করো ।

২। তোমার এলাকায় নিমগাছ রোপণের কর্মসূচি নেওয়া দরকার । এ কাজ করার জন্য তোমরা কী কী
করবে?



নমুনা প্রন
বহুনির্বাচনি প্রশ্ন
১। নিমগাছের ছাল নিয়ে লোকজন কী কাজে লাগায়?
ক. সিদ্ধ করে খায় খ. ভিজিয়ে খায়
গ. শুকিয়ে খায় ঘ. রান্না করে খায়
২। বাড়ির পাশে গজালে বিজ্ঞরা খুশি হয় কেন?
ক. এটা দেখতে সুন্দর খ. এটা উপকারী
গ. এটা পরিবেশ-বান্ধব ঘ. এটা আকারে ছোট
নিচের উদ্দীপকটি পড়ে ৩ ও ৪ নং প্রশ্নের উত্তর দাও।

গত আট বছর ধরে কৃষক গফুরের চাষাবাদের প্রধান অবলম্বন ছিল প্রিয় ষাড় মহেশ । বয়সের কারণে
মহেশ এখন আগের মতো কাজ করতে না পারলেও তার প্রতি গফুরের স্রেহ এতটুকু কমেনি । পরিবারের

সদস্য এবং প্রতিবেশীদের পরামর্শে মহেশকে বিক্রি না করে তাকে সন্তানত্রেহে লালন করতে থাকে দরিদ্র
গফুর ।
ক. উপকারী খ. সর্বংসহা
গ. আত্মত্যাগী ঘ. স্রেহ-কাঙাল
