### ❓ পাঠভিত্তিক প্রশ্ন ও উত্তর (Comprehension Q&A)

> ❓ **প্রশ্ন: ‘নিমগাছ’ গল্পে লেখক নিমগাছের রূপকে কোন মানবীয় চরিত্রকে তুলে ধরেছেন?**
> 💡 **উত্তর:** নিমগাছের রূপকে লেখক পরিবারের আত্মত্যাগী ও নিরবে সেবা করে যাওয়া গৃহবধূর চরিত্রকে তুলে ধরেছেন, যে নিঃস্বার্থভাবে সবাইকে দেয় কিন্তু নিজে অবহেলার পাত্রী হয়।

> ❓ **প্রশ্ন: গল্পের শেষ বাক্যটি (‘ওদের বাড়ির গৃহকর্ম-নিপুণা লক্ষ্মী বউটার ঠিক এক দশা’) কেন তাৎপর্যপূর্ণ?**
> 💡 **উত্তর:** এটি গল্পের ক্লাইম্যাক্স; গাছটির ওপর মানুষের নির্মম ব্যবহারের সাথে পরিবারের লক্ষ্মী বউটির আজীবন আত্মত্যাগ ও অবমূল্যায়নের বাস্তবতাকে এক নিমিষে স্পষ্ট করে দেয়।
