### ✍️ মূল পাঠ্যবইয়ের সৃজনশীল প্রশ্ন

সুমন ও কবির বাল্যবন্ধু ৷ দুজনই উচ্চ-শিক্ষায় শিক্ষিত। পেশাগত জীবনে সুমন বড় ব্যবসায়ী । গাড়ি,
বাড়ি, টাকা-কড়ি কোনো কিছুরই অভাব নেই তার । সবাই তাকে এক নামে চেনে। আর কবির
শিক্ষকতাকে পেশা হিসেবে বেছে নেয়। গত সিডরে তাদের গ্রাম লণ্ডভণ্ড হয়ে যায়। এ সময় কবির
তার ছাত্রদের নিয়ে ত্রাণসামগ্রী সংগ্রহ করে অসহায় মানুষদের কাছে পৌছে দেয়। তাদের আশ্রয়ের

ব্যবস্থা করে। অথচ সুমন ছুটে এসে সাহায্যের বদলে অসহায় মানুষদের কাছ থেকে নামমাত্র মূল্যে

ক. মানব জীবনে মুক্তির জন্য মোতাহের হোসেন চৌধুরী কয়টি উপায়ের কথা বলেছেন?
আত্মার অমৃত উপলব্ধি করা যায় না কেন?

উদ্দীপকের সুমনের মাঝে “শিক্ষা ও মনুষ্যতৃ" প্রবন্ধের যে দিকটি প্রকাশিত তা ব্যাখ্যা করো।
“কবিরের কাজে শিক্ষার অপ্রয়োজনীয় দিকটি উপস্থিত ”-_ শিক্ষা ও মনুষ্যত্ব" প্রবন্ধের
আলোকে মন্তব্যটি বিশ্লেষণ করো ।

