### 📚 শব্দার্থ ও টীকা : ও রভোয়া - ফরাসি ভাষার বাক্যবন্ধ ৷ অর্থ : আবার দেখা হবে । নরদানৰ -
মানুষের মতো দেখতে ভয়ঙ্কর জন্ত। এখানে বিশালদেহী মানুষ বোঝানো হয়েছে। আদরার্থে।
মর্তমান কলা - মায়ানমারের মার্তাবান দ্বীপে উৎপন্ন কলার জাত। রুজ - গাল রাঙানোর প্রসাধনী।
পান্তয়া - চিনির রসে ভেজানো ঘিয়ে ভাজা রসগোল্লা জাতীয় মিষ্টি। তাগদ - শক্তি। তম্বী_
তিরস্কার। বারকোশ - কাঠের তৈরি কানা উচু বড় থালা। পুনরপি - পুনরায়। ব্রহ্মরন্ধ - তালুর
কেন্দ্রবর্তী ছিদ্র । বপু - বড় দেহ। তনু -ক্ষীণ দেহ। উত্তমার্ধ - স্ত্রী, সহধর্মিণী ।

