### ❓ পাঠভিত্তিক প্রশ্ন ও উত্তর (Comprehension Q&A)

> ❓ **প্রশ্ন: ‘প্রবাস বন্ধু’ রচনায় আবদুর রহমানের সেবাযত্নের কোন বৈশিষ্ট্য ধরা পড়েছে?**
> 💡 **উত্তর:** আফগান ভৃত্য আবদুর রহমানের সরলতা, বিশ্বস্ততা, অপরিসীম আতিথেয়তা এবং গৃহকর্তার প্রতি অগাধ ভক্তি ও স্নেহের রূপ সুন্দরভাবে ধরা পড়েছে।

> ❓ **প্রশ্ন: কাবুলের আবহাওয়া ও পরিবেশের বিবরণ লেখক কীভাবে দিয়েছেন?**
> 💡 **উত্তর:** লেখক হাস্যরস ও সুতীক্ষ্ণ পর্যবেক্ষণের মাধ্যমে কাবুলের বরফাবৃত শীত, শুষ্ক আবহাওয়া এবং স্থানীয় মানুষের জীবনযাপন চমৎকারভাবে বর্ণনা করেছেন।
