### 📚 শব্দার্থ ও টীকা : হিংস্রালয়- হিংপ্র প্রাণীর বাসস্থান। গলগ্রস্থি- গলার বন্ধনী। ছাতলা- শ্যাওলা, দেয়ালে
জমা পুরানো ময়লা। আ্যান্দিন- এতদিন শব্দের কথ্যরূপ। ঠ্যায়রো- দীড়াও। ঠাওরালো- মনে করল।
চৌরঙ্গী- চার রাস্তার মিলনস্থল। কলকাতার একটি স্থানের নাম।

