### 📝 পাঠ-পরিচিতি : ভারত বিভাগের আগে ১৯৪৬ খিষ্টাব্দে এ অঞ্চলে ভয়াবহ হিন্দু-মুসলমান দাঙ্গা হয়েছিল ।
এসাম্প্রদায়িক দাঙ্গার পটভূমিতে “বনমানুষ" গল্পটি লিখিত । এ গল্পের লেখক বনবিভাগে সামান্য বেতনে
চাকরি করতেন। তিনি দ্বিগুণ বেতনে কলকাতায় চাকরি করতে আসেন । কলকাতায় এসে প্রথমে তার
নিজেকে সভ্য মানুষ মনে হতে থাকে । কিন্তু তিনি তখন সাম্প্রদায়িক হানাহানির মুখোমুখি হতে
পশুপাখিরাও এ রকম পরস্পরকে হত্যা করে না। তখন লেখক আবার বনবিভাগের চাকরিতে ফিরে


যাওয়ার সিদ্ধান্ত নেন। লেখকের কাছে এ শহরের সভ্য মানুষের চেয়ে বনে বসবাসকারী অশিক্ষিত মূর্খ
মানুষকে অধিক গ্রহণযোগ্য মনে হয়। “বনমানুষ' গল্পটি সংকীর্ণ ধর্ম-পরিচয়মুক্ত মানবিক বোধসম্পন্ন
চিন্তায় উদ্বুদ্ধ হতে সহায়তা করে; কারণ ধর্ম নিয়ে মানুষে সংঘাত মান্ষ পরিচয়টিকেই প্রশ্নবিদ্ধ করে ।
কেননা জীব হিসেবে মানুষ অন্য সব প্রাণীর তুলনায় জ্ঞান, বুদ্ধি ও সৃষ্টিশীলতায় শ্রেষ্ঠ ।
