### 📚 শব্দার্থ ও টীকা : জামী- লেখিকার ছোটো ছেলে। বিরান জনমানবহীন, পরিত্যক্ত, ফীকা। খুরপি-
মাটি খোঁড়ার জন্য ব্যবহৃত একপ্রকার ছোট খন্তা। শরীফ- লেখিকার স্বামী। রুমী- জামীর ভাই। অবরুদ্ধ
নিষ্ক্িয়তা_ রুদ্ধ বা আটক অবস্থায় কর্মহীনতা। কুটকৌশল- চতুরতা, দুর্দ্ধি। বেয়নেট- বন্দুকের
সঙ্গিন, বন্দুকের অগ্রভাগে লাগানো একপ্রকার বিষাক্ত ও ধারাল ছোরা । স্তস্তিত- হতবাক, বিস্মিত।
গোয়েবলস্‌ (১৮৯৭- ১৯৪৫)- জার্মান বংশোদ্ভূত হিটলারের সহযোগী, রাজনীতিতে প্রতিহিংসা
ও মিথ্যা রটনার প্রবর্তক । কথিকা- নির্দিষ্ট ও ক্ষুদ্র পরিসরে বর্ণনাত্বক রচনা। চরমপত্র- মৃত্যুর
পূর্বসময়ে লিখিত উপদেশ, শেষবারের মতো সতর্ক করে দেওয়ার জন্য প্রেরিত পত্র। ১৯৭) খ্রিষ্টাব্দের
মুক্তিযুদ্ধে মুক্তিযোদ্ধা ও দেশবাসীকে অনুপ্রেরণা দেওয়ার জন্য “স্বাধীনবাংলা বেতারকেন্দ্র থেকে এম.
হাস্যরসাত্বক এই কথিকাগুলো প্রচারিত হতো । এই কথিকাগুলো “চরমপত্র”নামে খ্যাত। আলটিমেটাম-
দেওয়া। মার্সি পিটিশন- শাস্তি থেকে অব্যাহতি চেয়ে আবেদন। লহমায়_ মুহূর্তে ।

