### ✍️ লেখক-পরিচিতি
> লেখক-পরিচিতি : মমতাজউদদীন আহমদ ১৮ই জানুয়ারি, ১৯৩৫ খিষ্টাব্দে পশ্চিমবঙ্গের মালদহে জন্মগ্রহণ
করেন। তিনি টাপাইনবাবগঞ্জের ভোলাহাট রামেশ্বরী ইনস্টিটিউশন থেকে প্রবেশিকা পরীক্ষায় উত্তীর্ণ হন।
পরে রাজশাহী কলেজ থেকে উচ্চ মাধ্যমিক এবং রাজশাহী বিশ্ববিদ্যালয় থেকে বাছলায় বিএ (অনার্স)
ও এমএ ডিগ্রি লাভ করেন। কর্মজীবনে তিনি বিভিন্ন সরকারি কলেজে অধ্যাপনার দায়িত্ব পালন করেন।
কিছু সময় তিনি ঢাকা বিশ্ববিদ্যালয়ের নাট্যকলা ও সঙ্গীত বিভাগে খন্ডকালীন অধ্যাপক ছিলেন। তিনি মূলত
নাট্যকার ও অভিনেতা হিসেবে খ্যাতিমান। বাংলাদেশের নাট্যশিল্প আন্দোলনের তিনি পুরোধা ব্যক্তিত্ব। তার
রচিত উল্লেখযোগ্য নাটক: স্বাধীনতা আমার স্বাধীনতা, বকুলপুরের স্বাধীনতা, সাত ঘাটের কানাকড়িঃ
তিনি বাংলা সাহিত্যে অবদানের জন্য বালা একাডেমি পুরস্কার, শিশু একাডেমি সাহিত্য পুরস্কার, একুশে
পদকসহ অসংখ্য পুরস্কার ও সম্মাননায় ভূষিত হন। ২০১৯ খিষ্টাব্দের ২রা জুন তিনি মৃত্যুবরণ করেন ॥|

