ইয়া আল্লা, মরে যাব যে মালিক । বলছি, হামাদের গায়ে দেখছি।

দেখতে জোয়ান?

চোখের মণি। লাঠি, ছোরা, বন্দুক সব চালাতে জানে । আর হাতের কজি (পিপেতে
ঘুষি মেরে) এই রকম লোহার মতোন শক্ত । একবার যদি হাত তুলে-

তার হাত আমি গুলি মেরে ভেঙে দিব।

খবরদার মালিক, খবরদার । ও কাজ ভুল করেও করতে যাবেন না হুজুর । একবার একটা
জিদ্দি পুলিশ ডাকাতটাকে ধরতে গিয়েছিল, রাইফেল তুলে মারতে যাবে, ব্যস নাই।
এক থাঞ্সড়ে পুলিশের এই গালের হাড্ডি ঝুর ঝুর ঝুর ঝুর করে পড়ে গেল।

তারপর?

তারপর আর কী হয়। পুলিশের রাইফেল হাতেই থাকল, এন্তেকাল এসে গেল ।
দারোগা সাহেবও এন্তেকাল!

না না মালিক। কতক্ষণ কোরবানির কাটা গরুর মতোন ছটফট ছটফট করল, পা দুটা টান
করল তারপর মানে যে যন্ত্রপাতি বন্ধ। এখন মানে যে একে আপনি কী বলবেন
চুপ কর। এই লোকটা বেঁচে থাকলে দেশের আমলা পুলিশের জান বাচবে কী করে?
বাচবে না মালিক। এই লোক থাকলে জোদ্দার কি মালদারের বংশের আর গোরে
মোমবান্তি জলবে না। হুজুর, আপনি তো ঘাটের এই ডাহিন দিকে নজর রেখেছেন লোকটা
এপথে আসবে বলেই _

কেন?

না, মানে যে, ডাহিন দিকে তাকালে যদি বাদিক দিয়ে আসে ।

তখন বাঁদিকে ঘুরে তাকাব!

ততক্ষণ কি সময় পাবেন মালিক । খোদা না খাস্তা, যদি আসেই, বাঘের মতোন লাফিয়ে


স্বাধানতা আমার স্বাধানতা ১১৭

তখন কী হবে গরীবুল্লাহঃ

কী আর হবে মালিক । আপনি মানে যে শুয়ে পড়লেন কতক্ষণ বেদিশা হয়ে পড়ে
থাকলেন, বাপদাদার নাম মনে করলেন, দেখলেন যে আসমান জমিন।

ভালো বলেছ গরীবুল্লাহ।

মালিক।

আল্লার রহমতে যদি ধরতে পারি, সরকারি বখশিশের ভাগ দাবি করবে?

না মালিক। হামি একটা সামান্য জীব। দেশের হাজার হাজার মানুষ হামার গান শুনে খুশি
লিয়ে কি করব।

তুমি একটা ভালো মানুষের পয়দা হে গরীবুল্লাহ। ঈমান ঠিক রেখে বেঁচে থাক । তোমাদের
মতো লোক দেখতে পাই না। চোর-ডাকাত দেখে দেখে পুলিশের রুহু পচে গেছে।

হয়, কিন্ত নিই না। আমার বাপের কসম আছে। মাঝে মধ্যে মনটা খিচড়ে ওঠে, কী
হবে মরা বাপের কথার মূল্য দিয়ে। কিন্তু বুকটা ধক্‌ ধক্‌ করে । এসব করি না বলেই
তো চব্বিশ বছরে চাকরিতে প্রমোশন হলো না।

ধরতে পারলে তো। তুমি যেসব কথা বলছ। লোকটা বুকভরা এত সাহস আর শক্তি
কোথায় পায় । তুমি শালা বানিয়ে বানিয়ে আমাকে ধোকা দিচ্ছ না তো?

মালিক হামি গান বানাই ঠিকই, কিন্তু মানুষ বানাব কোন সাহসে । মানুষ তো বানায়

[গান : একুল ভাঙে ওকুল গড়ে
এই তো নদীর খেলা]

গরীবুল্লাহ, এ তুমি কোন গান ধরলে । বুকটা হু হু করে ওঠে। বাংলার বাদশা পালিয়ে
যাচ্ছে, বাংলা পরাধীন, গাও ভাই গাও।

[গান চলছে!
বাংলার ভাগ্যাকাশে আজ দুর্যোগের ঘনঘটা, কে তাকে আশা দিবে, কে তাকে ভরসা
দিবে, কেমন সুন্দর কথা, যতবার শুনি মনে হয় বুকের মধ্যে ধরে রাখি ।
মালিক, হামাদের দেশ তো নদীর দেশ, সবুজ ধানের দেশ । তবুও হামরা এত দুঃখী
কেন মালিক?
সব তকদিরের খেলা রে ভাই । কপালে দুঃখ থাকলে সুখ তো পাবে না।
হামি আর কী বলব । আপনার দুঃখ কেউ বুঝল না, হামার জ্বালা কেউ বুঝতে চায় না।
হামাদের মগজের মধ্যে দিনরাত কিসব আলতুফালতু ভয় ঢুকিয়ে দিয়ে হামাদের শক্তি
কেড়ে নিচ্ছে, হামাদের সাহসকে গোর দিচ্ছে। আর এই সুযোগে যত সব জালেম
আল্লার নাম ভাঙিয়ে হামাদের শরীল থেকে শৌ শৌ করে রক্ত শুষে লিয়ে বিদেশে
পাচার করছে মালিক। আপনারা এসব রুখতে পারেন না কেন?
১১৮

রে

বাংলা সাহিত্য

তুমি শালা একটা উজবুক। বিড়াল হয়ে বাঘের মুখে থাপৃপড় দিতে চাও ।
হামার বাপজান বলত, গরীবুল্লাহ, বেটা অনাহক যারা তাল ঠুকে, তারা খুব বড় কিসিমের
গায়েন নয়। কথাটা ঠিক না বেঠিক একবার পরখ করবেন মালিক । হামাদের এই
ভাঙা ফুটা শরীল নিয়ে তামাম মানুষ যদি এক জায়গাতে হাজির হতে পারতাম, একবার
পারতাম, তখন বুঝা যেত কারা বিলাই আর কারা বাঘ। যুদ্ধই তো হয় না মালিক, মরণ
বাচার লড়াই। হামরা এই নদীর দেশের মানুষ একটা যুদ্ধ চাই মালিক, স্বাধীনতার জন্য যুদ্ধ ।
গরীবুল্লাহ তোমার কপালে ঢের দুঃখ আছে, এসব কথা বলো না।
সেই দুঃখই তো হামি চাহি মালিক । দুঃখের নদীতে আর কতকাল এমন করে ভাসব, তার
চেয়ে উঠুক না কেন আসমান জুড়ে কালো ম্যাঘ, উথাল পাথাল ঢেউ, আর প্রলয় বাতাস

[গান : খরবায়ু বয় বেগে

চারিদিক ছায় মেঘে

ওগো নেয়ে নাওখানি বাইয়ো]
এই গরীবুল্লাহ, তুমি এ গান পেলে কোথায়? এ তো তোমার স্কুল-কলেজের গান।
কিছু পড়ালেখা শিখেছ নাকি?
হামার গায়ের একটা ছাত্র শহরে পড়ে, তার মুখে শুনেছি মালিক । সেই ছাত্র এখন
জেলখানাতে বন্দি।
কিসের আসামি?
এ আপনার লাটসাহেবের মিটিং যে হলো, তার যে গপ্তগোল, তারই মধ্যে ছিল।
বেকুবের মতোন এসব হুজ্জতের মধ্যে যায় কেন?
ও ছেলে মানে যে আগুন দিয়ে তৈরি, অন্যায় কথা সহ্য করতে পারে না। বললে বলে,
গারদ ফাটক একদিন সব খান খান করে ভেঙে ফেলব । মালিক, আপনি তো ব্রিটিশ
আমলের ছাত্র । দেশের স্বাধীনতার জন্য আপনার মনটাতে হাহাকার করতো না।
রক্তের মধ্যে আগুন ধরে যায় এমন সব গান শিখতাম | একবার বিদায় দে মা ঘুরে আসি,
আমি হাসি হাসি পরব ফাসি দেখবে জগৎবাসী, তুমি জান নাকি গানটা?
বলে, মারলাম স্বদেশবাসী ।
সাবাস গরীবুল্লাহ, আবার গাও ।
আমি হাসি হাসি পরব ফীসি, দেখবে জগৎবাসী।
এখানে গাও, চিনতে যদি না পারিস মা, দেখবি গলায় ফীসি।
[দু'জনে এক সঙ্গে গান গাইছে

এসব বহুত পুরাতন কথা গরীবুল্লাহ, এখন যুগ জামানার ভিন্ন স্বাদ । দেশের মধ্যে নানান
রকম কথাবার্তা শুরু হয়েছে । কখন যে কী হয়। এই চাকরি করলে কী হবে, বুঝি গরীবুল্লাহ,
কিছু কিছু বুঝি । কিন্তু আমাদের হাত-পা যে বন্দি রে ভাই।


স্বাধানতা আমার স্বাধানতা ১১৯

লোক

গর

খু

মালিক, একটা কথা ভাবছি আর মনে মনে হাসছি। যে লোকটাকে ধরবার জন্য আপনি
এই আলো-আধারির রাতে ঘাট পাহারা দিচ্ছেন, ধরেন যে সেই লোকটা সত্যি সত্যি
আপনার কাছে হাজির হলো । আপনি তাকে দেখছেন, সেও আপনাকে দেখছে । দেখতে
দেখতে আপনার মনের মধ্যে প্রশ্ন হচ্ছে- কে এই লোক? একে তো আমি চিনি, আমার
সঙ্গে স্কুলে পড়ত, আমার বন্ধু । সে লোকটা আপনাকে বলছে- কী রে নূর মোহাম্মদ,
ঝুলিয়েছিস। আমাকে ধরলেই কি আগুন নিভে যাবে? স্বাধীনতার আগুন কখনো নেভে
না। মালিক, আপনি যখন ছাত্র ছিলেন তখন কি দেশের জন্য আপনাদের মন কীদত?
এখনো কাদে ।যদ্দিন বাচব দেশের জন্য কাদব। দেশকে ভালোবাসা তো পাপ নয়। যারা
স্বাধীনতা, তোমার আমার স্বাধীনতার জন্য কাজ করছে তাদেরকে আমিও ভালোবাসি গরীবুল্লাহ।
তাহলে আপনি আপনার বন্ধুকে ছেড়ে দিবেন না কেন মালিক?

তুমি আবার এ একই কথা বললে হে। বলছি তো আমার হাত-পা সব বন্দি। আমি
মালিক, হামরা যদি সেই যন্ত্রটাকে ভাঙতে বলি।

পারবে না, অসম্ভব ।

কেন অসম্ভব?

চুপ কর। একটা ডিঙি আসছে ।আমি জানতাম আসতেই হবে । আজ আমার ভাগ্যপরীক্ষা ।
জীবনের সঙ্গে লড়াই । বিপ্রবীকে ধরতে পারলে দু'হাজার টাকা পুরস্কার । আমার বড়
মেয়ের ধুমধাম করে বিয়ে দিব।

(গান) আমার ভাইয়ের রক্তে রাঙানো একুশে ফেব্রুয়ারি...

এই গরীবুল্লাহ, তোমার গান বন্ধ কর।

শালা ফকিরের বাচ্চা, গান বন্ধ কর। তোমার গলা টিপে গানের চৌদ্দ পুরুষকে জবাই
করব গরীবুল্লাহ।

কে শিস দিল?
[গরীবুল্লাহ নদীর ঘাটে নামছে]
এই শালা ঘাটে নামিস না। ঘুরে দীড়া, গুলি করব।
[গরীবুল্লাহ ঘুরে দীড়াল]

কে তুমি? ঠিকমতো পরিচয় দাও । কে তুমি?
ফকির গরীবুল্লাহ মালিক। শাদুল্লা গায়েনের ব্যাটা ।
ঝুট । মিথ্যা কথা বলো না। তুমি অন্য লোক।
অন্য কোন লোক? কে হতে পারি বলুন তো।
