### 📝 পাঠ-পরিচিতি : বাংলা একাডেমি থেকে প্রকাশিত শতবর্ষের নাটক নামক গ্রন্থ থেকে "ম্বাধীনতা
আমার স্বাধীনতা" নাটিকাটি সংকলিত ও সম্পাদিত হয়েছে। নাটিকাটি স্বদেশচেতনায় উদ্বুদ্ধ হওয়ার

শিক্ষা দেয়। নাট্যকার এখানে আমাদের দেশের পুলিশ সদস্যদের মানবতাবোধ এবং দেশাত্ববোধ
অত্যন্ত প্রাঞ্জল ভাষায় প্রকাশ করেছেন। দারোগা নূর মোহাম্মদ পুরস্কার ঘোষিত স্বদেশী আন্দোলনের

আসামিকে হাতের নাগালের মধ্যে পেয়েও তাকে ছেড়ে দিয়েছেন। অর্থপুরস্কারের লোভ জয় করে তিনি
দেশের স্বাধীনতার ও বিপ্লবী চেতনার সঙ্গে একাত্ম হয়ে গেছেন। একজন দারোগা, দুজন পুলিশ
সদস্য এবং একজন বিপ্নবীকে নিয়ে রচিত এ নাটকের প্রতিটি চরিত্রই আপন মহিমায় উজ্জ্বল হয়ে
উঠেছে। নাটকটি স্বদেশ চেতনায় উদ্বুদ্ধ হওয়ার শিক্ষা দেয় ।

কর্ম-অনুশীলন
১। শ্রেণিশিক্ষকের উপস্থিতিতে সবার অংশগ্রহণে পালাক্রমে নাটিকাটি অভিনয় করে দেখাও।
