### ✍️ মূল পাঠ্যবইয়ের সৃজনশীল প্রশ্ন

মাগফার আহমেদ চৌধুরী আজাদ । করাচি বিশ্ববিদ্যালয় থেকে ম্নাতক এবং ঢাকা বিশ্ববিদ্যালয়ের
আন্তর্জাতিক সম্পর্ক বিভাগ থেকে প্লাতকোত্তর পাশ করা স্বাধীনচেতা, দুরন্ত, টগবগে এক তরুণ । ১৯৭১
সালে যোগ দিলেন ক্রাক প্রাটুনে। সিদ্ধিরগঞ্জ পাওয়ার স্টেশন উড়িয়ে দেওয়াসহ বেশ কিছু অভিযানে
সফলতা দেখালেন । কিন্তু ৩০ আগস্ট ধরা পড়লেন পাকবাহিনীর হাতে । সহযোদ্ধাদের তথ্য নেওয়ার
জন্য তার উপরে চালানো হলো অমানুষিক অত্যাচার-নির্ধাতন । কিন্তু মুখ খুললেন না আজাদ, সব কিছু
সহ্য করলেন দাতে দাত কামড়ে । তার মা সাফিয়া বেগম রমনা থানায় তার সাথে দেখা করতে এলে
ভাত খেতে চেয়েছিলেন আজাদ । কিন্তু পরের দিন সাফিয়া বেগম ভাত নিয়ে গেলে ছেলেকে আর খুঁজে
পাননি । ছেলেকে ভাত খাওয়াতে না পারার কষ্টে আজাদের মা সারা জীবন আর ভাত খাননি ।

ক. গল্পকথকের সাথে তপুর শেষ দেখা হয়েছিল কোথায়?
খ. তপু ফিরে আসায় সবাই উদ্দিগ্ন হয়ে পড়েছিল কেন?
গ. উদ্দীপকের আজাদের সাথে “একুশের গল্প" রচনার কোন চরিত্রটি সাদৃশ্যপূর্ণ ব্যাখ্যা করো ।

ঘ. যুগে যুগে আজাদ, তপু, রাহাত, গল্প কথক- এঁরা এক কাতারে দাড়িয়ে যায় কেন? উদ্দীপক ও

