নিচের কোনটি ঠিক?


গ. 11 ও 111 ঘ. 1১11 ও 111
নিচের উদ্দীপকটি পড়ে ৩ ও ৪ নং প্রশ্নের উত্তর দাও।

নীলগঞ্জ স্কুলের শিক্ষার্থীবৃন্দ শিক্ষা সফরে কুষ্টিয়া গেল । কুষ্টিয়া শহরের কাছেই ছেউড়িয়ায় লালনের
মুগ্ধ করল। সেখান থেকে তারা শিলাইদহ রবীন্দ্র কুঠিবাড়িতে গেল। কুঠিবাড়ির ইটের কারুকার্য
তাদের ভালো লাগল । কুঠিবাড়ির কাছেই শিলাইদহ ঘাট । তাদের মনে পড়ল রবীন্দ্রনাথ বজরা করে এই
ঘাট থেকেই পদ্মার বুকে ভেসে ভেসে প্রাকৃতিক সৌন্দর্য দেখতে দেখতে সৃষ্টিশীলতায় মগ্ন থাকতেন।



৩। উদ্দীপকে “আমাদের সংস্কৃতি” প্রবন্ধে বিধৃত দিকটি হলো-

ক. বন্তগত সংস্কৃতি খ. মানস সংস্কৃতি
গ. নগর সংস্কৃতি ঘ. বাউল সংস্কৃতি

৪। উদ্দীপকের অনুভূতির সাথে “আমাদের সংস্কৃতি' প্রবন্ধের কোন বিষয়টি সামঞ্তস্যপূর্ণ?

ক. লোকসাহিত্য ও শিষ্ট সাহিত্যের ভেদ আছে

খ. বাংলার সংস্কৃতিতে অনেক সংস্কৃতি-প্রবাহের দান এসে মিশেছে

গ. বাংলার প্রকৃতি ও ভৌগোলিক অবস্থান আমাদের সংস্কৃতিকে স্বাতন্ত্য দিয়েছে
ঘ. উচ্চবর্ণের সংস্কৃতির সঙ্গে নিম্নবর্ণের সংস্কৃতির প্রভেদ আছে

---

### ✍️ মূল পাঠ্যবইয়ের সৃজনশীল প্রশ্ন

বাঙালি সংকর জাতি। রাজনৈতিক, সাংস্কৃতিক ও ধর্মীয় কারণে এদেশের মানুষ একদিকে
সহনশীল অন্যদিকে বিদ্রোহী । এ দেশের মানুষ নানা সম্কট মোকাবিলা করে ধর্ম ও সংস্কৃতিকে
অভিযোজিত করেছে। এই অভিযোজন প্রক্রিয়ায় যুক্ত হয়েছে নানা আয়োজন । শাসনশক্তির
রূপান্তর, ধর্মান্তর প্রক্রিয়া এখন ইহজাগতিক ও অসাম্প্রদায়িক চেতনাকে বিলীন করেনি ।

উচ্চবর্গের সংস্কৃতি বলতে কী বোঝ?

উদ্দীপকের ভাবটি “আমাদের সংস্কৃতি' প্রবন্ধের কোন দিককে প্রতিফলিত করে? ব্যাখ্যা করো ।
“সাহিত্য ও সংস্কৃতির সবক্ষেত্রেই শেষ পর্যন্ত ধমীয় বস্তর চেয়ে বড়ো হয়ে উঠেছে
মানবিকতা" লেখকের এই অভিমত উদ্দীপকে কতটা প্রতিফলিত হয়েছে - মূল্যায়ন করো ।

---

### ❓ পাঠভিত্তিক প্রশ্ন ও উত্তর (Comprehension Q&A)

> ❓ **প্রশ্ন: ‘আমাদের সংস্কৃতি’ প্রবন্ধে আনিসুজ্জামান সংস্কৃতির কোন বৈশিষ্ট্য ব্যাখ্যা করেছেন?**
> 💡 **উত্তর:** সংস্কৃতি হলো মানুষের সামগ্রিক জীবনপ্রণালী, চিন্তা, আচার-আচরণ ও মূল্যবোধের প্রকাশ; এটি স্থবির নয়, বরং যুগের সাথে পরিবর্তনশীল ও সমন্বয়ধর্মী।

