## 📖 মূল পাঠ (গদ্য)

বাঙলা শব্দ
হুমায়ুন আজাদ

[লেখক -পরিচিতি : বাংলাদেশের বিশিষ্ট গদ্যশিল্পী, ভাষাবিজ্ঞানী, ওপন্যাসিক ও কবি হুমায়ুন আজাদ ১৯৪৭
খিষ্টাব্দের ২৮শে এপ্রিল মুলসীগঞ্জ জেলার বিক্রমপুরের অন্তর্গত রাড়িখাল গ্রামে জনগ্রহণ করেন। অত্যন্ত
মেধাবী হুমায়ুন আজাদ দীর্ঘদিন ঢাকা বিশ্ববিদ্যালয়ের বাংলা বিভাগে অধ্যাপনা করেছেন। তার উল্লেখযোগ্য
অশ্রবিন্দুঃ উপন্যাস- ছাগ্জা্ন হাজার বগর্মাইল, সব কিছু ভেঙে পড়ে, গল্প- যাদুকরের মৃত্যু, প্রবন্ধ- নিবিড়
নীলিমা, বাঙলা ভাষার শক্রমিব্র, বাক্যতত্, লাল নীল দীপাবলি, কতো নদী সরোবর ইত্যাদি । তিনি বাংলা
একাডেমি পুরস্কারসহ অন্যান্য অনেক পুরস্কার লাভ করেছেন। হুমায়ুন আজাদ ২০০৪ খিষ্টাব্দের ১২ই আগস্ট
মৃত্যুবরণ করেন |]

বাংলা ভাষার একরকম শব্দকে বলা হয় তিত্তব শব্দ'। আরেক রকম শব্দকে বলা তৎসম শব্দ'।
এবং আরেক রকম শব্দকে বলা হয় “অর্ধতৎসম শব্দ' | এ-তিন রকম শব্দ মিলে গড়ে উঠেছে বাংলা
তারা “তৎ অর্থাৎ “তা” বলতে বোঝাতেন “সংস্কৃত' (এখন বলি প্রাচীন ভারতীয় আর্য) ভাষাকে । আর
'ভব' শব্দের অর্থ 'জাত, উৎপন্ন" । তাই “তন্তব' শব্দের অর্থ হলো “সংস্কৃত থেকে জন্ম নেওয়া»আর “তৎসম
শব্দের অর্থ হচ্ছে “সংস্কৃতের সমান" অর্থাৎ সংস্কৃত। বাংলা ভাষার শব্দের শতকরা বায়ান্নটি শব্দ
“তভব' ও অর্ধ-তৎসম”। শতকরা চুয়াল্িশটি “তৎসম” । তাই বাংলা ভাষার শতকরা ছিয়ানব্বইটিই
মৌলিক বা বাংলা শব্দ।

প্রাচীন ভারতীয় আর্ধভাষার. বিপুল পরিমাণ শব্দ বেশ নিয়মকানুন মেনে রূপ বদলায় মধ্যভারতীয়
আর্ধভাষায় অর্থাৎ প্রাকৃতে। পরিণত হয় প্রাকৃত শব্দে। শব্দগুলো গা ভাসিয়ে দিয়েছিলো পরিবর্তনের
স্রোতে । প্রাকৃতে আসার পর আবার বেশ নিয়মকানুন মেনে তারা বদলে যায়। পরিণত হয় বাংলা শব্দে ।
এগুলোই তত্তব শব্দ। এ-পরিবর্তনের স্রোতে ভাসা শব্দেই উজ্জ্বল বাংলা ভাষা । তবে তত্তব শব্দগুলো
সংস্কৃত বা প্রাচীন ভারতীয় আর্ধভাষা থেকেই শুধু আসেনি । এসেছে আরো কিছু ভাষা থেকে । তবে
প্রাচীন ভারতীয় আর্যভাষা থেকেই এসেছে বেশি সংখ্যক শব্দ।

চাদ" “মাছ” 'এয়ো”, দুধ" বাশি" । এগুলো প্রাচীন ভারতীয় আর্ধভাষা থেকে নিয়ম মেনে প্রাকৃতের
ভেতর দিয়ে এসেছে বাংলায়। 'চাদ' ছিল সংস্কৃতে “চন্দ্র, প্রাকৃতে ছিল 'চন্দ'। বাংলায় “চাদ।
“মাছ' ছিল “মৎস্য” সংস্কৃতে, প্রাকৃতে হয় “মচ্ছ'। বাংলায় 'মাছ'। “এয়ো” ছিল সংস্কৃতে
“অবিধবা?। প্রাকৃতে হয় “অবিহবা"। বাংলায় “এয়ো"। “দুধ” ছিল সংস্কৃতে “দুগ্ধ; প্রাকৃতে হয়
'দুদ্ধ' । বাংলায় হয় “দুধ” । “বাঁশি ছিল “বংশী' সংস্কৃতে। প্রাকৃতে হয় “বংসী'। বাংলায় “বাশি ।
বেশ নিয়ম মেনে, অনেক শতক পথ হেঁটে এসেছে এ-তীর্থযাত্রীরা। আমাদের সবচেয়ে প্রিয়রা।

আরো আছে কিছু তীর্থযাত্রী, যারা পথ হেঁটেছে আরো বেশি। তারা অন্য ভাষার । তারা প্রথমে
ঢুকেছে সংস্কৃতে, তারপর প্রাকৃতে। তারপর এসেছে বাংলায়। এরাও তন্তব শব্দ। মিশে আছে
বাংলা ভাষায় ।


খাল" আর “ঘড়া”। খুব নিকট শব্দ আমাদের | খাল" শব্দটি তামিল ভাষার “কাল' থেকে এসেছে।
'কাল' সংস্কৃতে হয় 'খল্প”। প্রাকৃতে হয় 'খন্প' ৷ বাংলায় “খাল” তামিল-মলয়ালি ভাষায় একটি শব্দ
ছিল কুটম'। সংস্কৃতে সেটি হয় ঘট । প্রাকৃতে হয় “ঘড়' । বাংলায় “ঘড়া? ।

টাকা) থেকে। 'দ্রাখুমে' সংস্কতে হয় দ্রম্য। প্রাকৃতে '“দম্ম"। বাংলায় “দাম"। খিক ভাষায় একটি শব্দ ছিল
