### ❓ পাঠভিত্তিক প্রশ্ন ও উত্তর (Comprehension Q&A)

> ❓ **প্রশ্ন: ‘বাঙলা শব্দ’ প্রবন্ধে হুমায়ুন আজাদ বাংলা ভাষার শব্দভাণ্ডারকে কীভাবে বিন্যস্ত করেছেন?**
> 💡 **উত্তর:** তিনি বাংলা শব্দের উদ্ভব, বিবর্তন এবং তৎসম, তদ্ভব, দেশি ও বিদেশি শব্দের মিশ্রণে ভাষার সমৃদ্ধি ও গতিশীলতার ইতিহাস তুলে ধরেছেন।

> ❓ **প্রশ্ন: বাংলা ভাষার শব্দভাণ্ডার কেন এত বৈচিত্র্যময়?**
> 💡 **উত্তর:** ইতিহাসের বিভিন্ন যুগে নানা জাতি ও সংস্কৃতির সংস্পর্শে এসে তাদের শব্দ আত্মস্থ করে বাংলা ভাষা নিজের প্রকাশক্ষমতাকে অসাধারণ সমৃদ্ধ করেছে।
